INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C1','kor',2,1,'u7',1,'고운 말이 필요한 까닭 — 같은 일이라도 어떻게 말하느냐에 따라 듣는 사람의 기분과 사이가 달라지며, 듣는 사람을 생각하며 하는 고운 말은 마음을 따뜻하게 하고 사이를 가깝게 함을 알기',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C2','kor',2,1,'u7',1,'거친 말을 고운 말로 바꾸기 — 탓하거나 놀리거나 명령하는 거친 말을 같은 뜻을 곱게 전하는 말(부탁하는 말·마음을 헤아리는 말)로 바꾸어 상황에 맞게 말하기',ARRAY['2국01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C3','kor',2,1,'u7',3,'경험을 떠올리며 이야기 듣기 — 이야기를 들으며 누가·무슨 일을 했는지·왜 그랬는지 내용을 확인하고 비슷한 내 경험을 떠올려 더 잘 이해하기',ARRAY['2국01-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C4','kor',2,1,'u7',3,'인물의 경험과 내 경험 비교하기 — 인물이 겪은 일과 그때의 마음을 찾고, 겪은 일이 똑같지 않아도 비슷한 마음이 들었던 내 경험을 떠올려 같은 점·다른 점 말하기',ARRAY['2국01-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C5','kor',2,1,'u7',5,'발표할 경험 정리하기 — 한 일·본 일·들은 일 가운데 기억에 남는 경험을 골라 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌을 빠짐없이 정리하기',ARRAY['2국01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C6','kor',2,1,'u7',5,'바른 자세로 발표하고 듣기 — 듣는 사람을 바라보며 알맞은 목소리 크기로 말끝까지 또박또박 발표하고, 듣는 사람은 발표하는 친구를 바라보며 끝까지 들은 뒤 궁금한 점을 묻기',ARRAY['2국01-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C7','kor',2,1,'u7',7,'상황 속 상대의 마음 짐작하기 — 대화나 상황에서 상대가 왜 그렇게 했는지(일부러인지 실수인지)와 지금 어떤 마음일지(속상함·억울함·당황함·미안함) 짐작하기',ARRAY['2국01-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C8','kor',2,1,'u7',7,'마음을 생각하며 고운 말로 대화하기 — 상대의 마음을 먼저 생각하고 상황에 맞게 「고마워」·「미안해」·「괜찮아?」·부탁하는 말 같은 고운 말로 대화하여 다툼을 풀기',ARRAY['2국01-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C9','kor',2,1,'u7',9,'인물의 마음을 생각하며 이야기 읽기 — 이야기 속 인물의 마음이 무엇 때문에 어떻게 바뀌는지 짐작하고, 흉내 내는 말(데굴데굴·엉금엉금·방긋·둥실둥실)이 인물의 모습과 마음을 생생하게 나타냄을 알기',ARRAY['2국01-02']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C10','kor',2,1,'u7',9,'고운 말로 마음 전하기 — 고마운 마음·미안한 마음·축하하는 마음을 받는 사람·전하고 싶은 마음·그 까닭이 드러나게 고운 말이나 마음 쪽지로 전하기',ARRAY['2국01-02']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C11','kor',2,1,'u7',12,'고운 말을 즐겁게 연습하고 실천하기 — 고운 말 맞추기 놀이로 고운 말을 익히고, 놀이에서 연습한 고운 말을 집과 학교 생활에서 상황에 맞게 실천하기',ARRAY['2국01-02']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u7-C12','kor',2,1,'u7',14,'확실한 일은 또렷하게 말하기 — 내가 겪어서 확실히 아는 일은 「~것 같아요」 대신 「~했어요」·「~예요」처럼 또렷하게 말하고, 「~것 같아요」는 짐작할 때에 쓰기',ARRAY['2국01-04']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X01','kor',2,'u7',ARRAY['K2-1-u7-C1','K2-1-u7-C11']::text[],'말이 듣는 사람의 기분과 사이에 주는 영향을 생각하지 않는다(뜻만 같으면 기분도 같다, 어른 앞에서만 고운 말을 쓰면 된다)','그 말을 내가 들었다면 기분이 어땠을지 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X02','kor',2,'u7',ARRAY['K2-1-u7-C2','K2-1-u7-C8','K2-1-u7-C10','K2-1-u7-C11']::text[],'상황과 고운 말의 짝을 헷갈린다(도움을 받고 「미안해」, 잘못하고 「고마워」, 생일에 「미안해」)','「고마운 일인가, 미안한 일인가, 기쁜 일인가?」 먼저 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X03','kor',2,'u7',ARRAY['K2-1-u7-C1','K2-1-u7-C2','K2-1-u7-C8','K2-1-u7-C11']::text[],'놀리거나 탓하거나 비꼬는 말을 고운 말로 여기거나, 부탁하는 말 끝에 놀리는 말을 붙여도 괜찮다고 여긴다','말 끝까지 다 듣고 「듣는 사람 마음이 따뜻해질까?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X04','kor',2,'u7',ARRAY['K2-1-u7-C3','K2-1-u7-C5','K2-1-u7-C9','K2-1-u7-C11']::text[],'이야기·발표·맞추기판에 없는 내용을 있다고 하거나 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X05','kor',2,'u7',ARRAY['K2-1-u7-C3','K2-1-u7-C4','K2-1-u7-C5','K2-1-u7-C7','K2-1-u7-C9']::text[],'인물을 뒤바꿔 다른 인물이 한 일·마음을 말한다','누가 한 일인지 이름에 동그라미 치고 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X06','kor',2,'u7',ARRAY['K2-1-u7-C4','K2-1-u7-C5']::text[],'있었던 일과 그때의 마음(생각이나 느낌)을 헷갈린다','「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X07','kor',2,'u7',ARRAY['K2-1-u7-C4']::text[],'이야기와 상관없는 일을 비슷한 경험으로 떠올리거나, 똑같은 일을 겪어야만 비슷한 경험이라고 여긴다','「그때 인물과 비슷한 마음이었나?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X08','kor',2,'u7',ARRAY['K2-1-u7-C5']::text[],'발표 내용에 언제·어디에서·생각이나 느낌을 빠뜨리거나 경험과 상관없는 내용을 넣는다','언제 · 어디서 · 무슨 일 · 느낌 네 손가락을 꼽으며 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X09','kor',2,'u7',ARRAY['K2-1-u7-C5']::text[],'발표 내용과 질문(언제?·어디에서?·무슨 일?)의 짝을 헷갈린다','질문을 붙여 「~에」 대답이 되는지 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X10','kor',2,'u7',ARRAY['K2-1-u7-C6']::text[],'바르지 않은 발표 자세(바닥 보기·말끝 흐리기·너무 작거나 큰 소리)를 바르다고 여긴다','맨 뒤 친구가 잘 듣고 내 얼굴을 볼 수 있는지 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X11','kor',2,'u7',ARRAY['K2-1-u7-C6']::text[],'바르지 않은 듣는 자세(끼어들기·딴짓·놀리기)를 괜찮다고 여긴다','발표가 끝날 때까지 기다렸다가 손 들고 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X12','kor',2,'u7',ARRAY['K2-1-u7-C2','K2-1-u7-C7','K2-1-u7-C8']::text[],'상대의 마음은 생각하지 않고 내 기분대로만 말하거나, 일부러 한 일이 아닌데도 상대를 탓한다','「일부러 그랬을까?」 먼저 생각하고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X13','kor',2,'u7',ARRAY['K2-1-u7-C7','K2-1-u7-C9']::text[],'상황에 맞지 않게 상대의 마음을 짐작한다(다친 친구가 기쁠 것이다, 도와준 사람이 싫었을 것이다)','내가 그 사람이라면 어떤 마음일지 바꿔 생각해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X14','kor',2,'u7',ARRAY['K2-1-u7-C9']::text[],'흉내 내는 말의 뜻을 헷갈린다(엉금엉금 → 빠르게, 둥실둥실 → 떨어지는 모양)','흉내 내는 말을 몸짓으로 따라 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X15','kor',2,'u7',ARRAY['K2-1-u7-C10']::text[],'마음은 말로 전하지 않아도 된다고 여기거나, 쪽지에 받는 사람·쓴 사람·무엇이 고마운지(미안한지)를 헷갈리거나 빠뜨린다','누구에게 · 어떤 마음 · 왜 — 세 가지가 있는지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X16','kor',2,'u7',ARRAY['K2-1-u7-C11']::text[],'고운 말 맞추기 놀이의 방법을 헷갈리거나, 고운 말은 놀이할 때만 쓰면 된다고 여긴다','놀이에서 쓴 고운 말을 오늘 누구에게 쓸지 정해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X17','kor',2,'u7',ARRAY['K2-1-u7-C12']::text[],'확실한 일인데도 「~것 같아요」를 버릇처럼 쓰거나, 짐작하는 일까지 단정해서 말한다','「내가 직접 겪었나?」 물어보고 겪었으면 「~했어요」로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u7-X18','kor',2,'u7',ARRAY['K2-1-u7-C1','K2-1-u7-C2','K2-1-u7-C3','K2-1-u7-C4','K2-1-u7-C5','K2-1-u7-C6','K2-1-u7-C7','K2-1-u7-C8','K2-1-u7-C9','K2-1-u7-C10','K2-1-u7-C11','K2-1-u7-C12']::text[],'묻는 말을 거꾸로 읽는다 — 알맞지 않은↔알맞은, 잘못↔바르게, 아닌↔맞는','물음의 「않은·잘못·아닌」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#1','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],true,'{"seq":1,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「내가 도와줄게.」","correct":true},{"t":"「저리 비켜.」","mis":"K2-1-u7-X03"},{"t":"「그것도 못하니?」","mis":"K2-1-u7-X03"}],"explanation":["「내가 도와줄게.」는 듣는 사람을 생각하는 고운 말이에요.","「저리 비켜.」와 「그것도 못하니?」는 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「고마워.」","correct":true},{"t":"「시끄러워.」","mis":"K2-1-u7-X03"},{"t":"「바보야.」","mis":"K2-1-u7-X03"}],"explanation":["「고마워.」는 마음을 따뜻하게 하는 고운 말이에요.","「시끄러워.」와 「바보야.」는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#2','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',1,'ox','auto','같은 일이라도 어떻게 말하느냐에 따라 듣는 사람의 기분이 달라져요.',ARRAY['K2-1-u7-X01']::text[],true,'{"seq":2,"concept":"K2-1-u7-C1","difficulty":1,"kind":"ox","stem":"같은 일이라도 어떻게 말하느냐에 따라 듣는 사람의 기분이 달라져요.","answer":"O","reason_options":[{"t":"고운 말은 마음을 따뜻하게 하고 거친 말은 마음을 아프게 하니까","correct":true},{"t":"뜻만 같으면 듣는 사람의 기분은 늘 똑같으니까","mis":"K2-1-u7-X01"}],"mis":"K2-1-u7-X01","explanation":["같은 부탁도 곱게 말하면 기분 좋게 들어 줘요.","거칠게 말하면 뜻이 같아도 마음이 상해요.","말할 때 듣는 사람의 마음을 생각해요."],"variant_rule":{"alt":[{"stem":"친구에게 거친 말을 해도 친구 사이는 그대로예요.","answer":"X","reason_options":[{"t":"거친 말을 들으면 마음이 상해서 사이가 멀어질 수 있으니까","correct":true},{"t":"친구는 무슨 말을 들어도 마음이 상하지 않으니까","mis":"K2-1-u7-X01"}],"explanation":["거친 말은 친구의 마음을 아프게 해요.","마음이 상하면 사이가 멀어질 수 있어요.","고운 말은 사이를 가깝게 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#3','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',1,'mc','auto','그림을 그리다가 물감을 쏟아 속상한 친구에게 할 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],true,'{"seq":3,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"그림을 그리다가 물감을 쏟아 속상한 친구에게 할 고운 말은 어느 것인가요?","options":[{"t":"「괜찮아, 같이 닦자.」","correct":true},{"t":"「그러게 조심하랬잖아.」","mis":"K2-1-u7-X12"},{"t":"「하하, 다 망쳤네!」","mis":"K2-1-u7-X03"}],"explanation":["속상한 친구의 마음을 헤아려 돕는 말이에요.","「조심하랬잖아.」는 친구를 탓하는 말이에요.","친구의 실수를 웃음거리로 삼으면 안 돼요."],"variant_rule":{"alt":[{"stem":"받아쓰기에서 한 문제를 틀려 속상한 친구에게 할 고운 말은 어느 것인가요?","options":[{"t":"「다음에는 더 잘할 수 있을 거야.」","correct":true},{"t":"「그것도 틀렸어?」","mis":"K2-1-u7-X03"},{"t":"「나는 다 맞았는데.」","mis":"K2-1-u7-X12"}],"explanation":["속상한 친구에게 힘을 주는 말이에요.","「그것도 틀렸어?」는 친구를 놀리는 말이에요.","내 자랑만 하면 친구의 마음을 생각하지 않은 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#4','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',1,'mc','auto','고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],true,'{"seq":4,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람의 마음을 따뜻하게 하고 사이를 가깝게 해 주니까","correct":true},{"t":"말을 빨리 끝낼 수 있으니까","mis":"K2-1-u7-X01"},{"t":"선생님이 계실 때만 지키면 되니까","mis":"K2-1-u7-X01"}],"explanation":["고운 말은 듣는 사람의 기분을 좋게 해요.","말이 빨리 끝나는 것은 고운 말을 쓰는 까닭이 아니에요.","고운 말은 언제 어디서나 써요."],"variant_rule":{"alt":[{"stem":"고운 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"듣는 사람을 생각하며 하는 말이에요","correct":true},{"t":"어른에게만 쓰는 말이에요","mis":"K2-1-u7-X01"},{"t":"크게 소리치는 말이에요","mis":"K2-1-u7-X03"}],"explanation":["고운 말은 듣는 사람의 마음을 생각하며 하는 말이에요.","친구와 동생에게도 고운 말을 써요.","소리를 크게 낸다고 고운 말이 되지는 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#5','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"너 때문에 늦었잖아!","r":"다음엔 조금 서둘러 줄래?"},{"l":"그것도 몰라?","r":"내가 같이 알아볼게."},{"l":"비켜!","r":"잠깐 지나가도 될까?"}],"mis":"K2-1-u7-X02","explanation":["탓하는 말은 부탁하는 말로 바꿔요.","모른다고 놀리지 말고 함께 알아보자고 해요.","「비켜!」 대신 지나가도 되는지 물어봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"시끄러워!","r":"조금만 작게 말해 줄래?"},{"l":"내 거 만지지 마!","r":"쓰기 전에 먼저 물어봐 줄래?"},{"l":"느림보야!","r":"천천히 해도 괜찮아."}],"explanation":["「시끄러워!」 대신 작게 말해 달라고 부탁해요.","만지지 말라고 소리치지 말고 먼저 물어봐 달라고 해요.","느리다고 놀리지 말고 기다려 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#6','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'mc','auto','친구가 내 지우개를 말없이 가져가 썼어요. 내 마음을 고운 말로 전한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],true,'{"seq":6,"concept":"K2-1-u7-C2","difficulty":2,"kind":"mc","stem":"친구가 내 지우개를 말없이 가져가 썼어요. 내 마음을 고운 말로 전한 것은 어느 것인가요?","options":[{"t":"「다음에는 쓰기 전에 말해 줄래?」","correct":true},{"t":"「왜 마음대로 가져가? 도둑이야?」","mis":"K2-1-u7-X12"},{"t":"「가져가 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["바라는 것을 부탁하는 말로 전했어요.","친구를 도둑이라고 하면 마음이 크게 상해요.","고마운 일이 아니니 「고마워.」는 맞지 않아요."],"variant_rule":{"alt":[{"stem":"짝이 수업 시간에 자꾸 내 책상을 흔들어요. 내 마음을 고운 말로 전한 것은 어느 것인가요?","options":[{"t":"「책상이 흔들려서 글씨가 삐뚤어져. 조금만 조심해 줄래?」","correct":true},{"t":"「야, 그만 좀 해!」","mis":"K2-1-u7-X12"},{"t":"「축하해!」","mis":"K2-1-u7-X02"}],"explanation":["까닭을 말하고 부탁하는 말로 전했어요.","「그만 좀 해!」는 화난 내 기분만 쏟아 낸 말이에요.","축하할 일이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#7','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',2,'mc','auto','「또 늦었어? 맨날 굼벵이야.」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],true,'{"seq":7,"concept":"K2-1-u7-C1","difficulty":2,"kind":"mc","stem":"「또 늦었어? 맨날 굼벵이야.」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하고 서운하다","correct":true},{"t":"고맙고 기쁘다","mis":"K2-1-u7-X01"},{"t":"신나고 자랑스럽다","mis":"K2-1-u7-X01"}],"explanation":["놀리는 말을 들으면 속상하고 서운해요.","고맙거나 신날 까닭이 없어요.","내가 들었다면 어땠을지 떠올려요."],"variant_rule":{"alt":[{"stem":"「같이 하자. 내가 도와줄게.」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"든든하고 고맙다","correct":true},{"t":"창피하고 화난다","mis":"K2-1-u7-X01"},{"t":"슬프고 외롭다","mis":"K2-1-u7-X01"}],"explanation":["도와주겠다는 말을 들으면 든든하고 고마워요.","창피하거나 화날 까닭이 없어요.","고운 말은 마음을 따뜻하게 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#8','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'error','auto','친구에게 한 말이에요. 고운 말이 아닌 말을 한 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C2","difficulty":2,"kind":"error","stem":"친구에게 한 말이에요. 고운 말이 아닌 말을 한 친구는 누구인가요?","options":[{"t":"도담 — 「네 그림은 왜 이렇게 이상해?」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"하늘 — 「네 그림 색깔이 참 예쁘다.」","mis":"K2-1-u7-X18"},{"t":"윤서 — 「같이 그리니까 더 재미있다.」","mis":"K2-1-u7-X18"}],"explanation":["「왜 이렇게 이상해?」는 친구 그림을 깎아내리는 말이에요.","하늘이와 윤서는 고운 말을 했어요.","물음의 「아닌」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구에게 한 말이에요. 고운 말이 아닌 말을 한 친구는 누구인가요?","options":[{"t":"건우 — 「넌 달리기 꼴찌잖아.」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"채원 — 「끝까지 달린 게 멋졌어.」","mis":"K2-1-u7-X18"},{"t":"지우 — 「다음엔 같이 연습하자.」","mis":"K2-1-u7-X18"}],"explanation":["「꼴찌잖아.」는 친구를 놀리는 말이에요.","채원이와 지우는 고운 말을 했어요.","물음의 「아닌」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#9','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C2',2,'blank','auto','친구가 내 실내화를 찾아 주었어요. 「(     ) 덕분에 찾았어.」 빈칸에 알맞은 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],true,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"blank","stem":"친구가 내 실내화를 찾아 주었어요. 「(     ) 덕분에 찾았어.」 빈칸에 알맞은 고운 말은 어느 것인가요?","options":[{"t":"고마워.","correct":true},{"t":"미안해.","mis":"K2-1-u7-X02"},{"t":"축하해.","mis":"K2-1-u7-X02"}],"explanation":["도움을 받았으니 「고마워.」라고 해요.","「미안해.」는 잘못했을 때 하는 말이에요.","「축하해.」는 기쁜 일이 있을 때 하는 말이에요."],"variant_rule":{"alt":[{"stem":"내가 실수로 친구의 발을 밟았어요. 「(     ) 많이 아프지?」 빈칸에 알맞은 고운 말은 어느 것인가요?","options":[{"t":"미안해.","correct":true},{"t":"고마워.","mis":"K2-1-u7-X02"},{"t":"잘했어.","mis":"K2-1-u7-X02"}],"explanation":["잘못했으니 「미안해.」라고 해요.","「고마워.」는 도움을 받았을 때 하는 말이에요.","칭찬할 일이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_basic#10','kor',2,1,'u7','L01','g2_1_kor_u7_L01_basic','lesson_basic','K2-1-u7-C1',3,'mc','auto','하준이는 친구에게 「느림보!」라고 놀렸어요. 그 뒤로 친구가 하준이와 놀지 않으려고 해요. 이 일로 알 수 있는 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X01']::text[],true,'{"seq":10,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"하준이는 친구에게 「느림보!」라고 놀렸어요. 그 뒤로 친구가 하준이와 놀지 않으려고 해요. 이 일로 알 수 있는 것은 어느 것인가요?","options":[{"t":"거친 말은 친구 사이를 멀어지게 할 수 있어요","correct":true},{"t":"놀리는 말은 장난이라서 괜찮아요","mis":"K2-1-u7-X03"},{"t":"친구가 놀지 않는 것은 말과 상관없어요","mis":"K2-1-u7-X01"}],"explanation":["놀리는 말에 마음이 상해서 친구가 멀어졌어요.","장난이라도 듣는 사람이 아프면 거친 말이에요.","말은 친구 사이에 큰 힘을 가져요."],"variant_rule":{"alt":[{"stem":"서윤이가 친구에게 「힘내, 할 수 있어!」라고 말해 주었더니 친구가 끝까지 해냈어요. 이 일로 알 수 있는 것은 어느 것인가요?","options":[{"t":"고운 말은 친구에게 힘을 줄 수 있어요","correct":true},{"t":"말은 친구의 마음에 아무 힘이 없어요","mis":"K2-1-u7-X01"},{"t":"「힘내」는 거친 말이에요","mis":"K2-1-u7-X03"}],"explanation":["응원하는 고운 말이 친구에게 힘이 되었어요.","말은 마음에 큰 힘을 가져요.","「힘내」는 고운 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#1','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',2,'mc','auto','고운 말이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":1,"concept":"K2-1-u7-C2","difficulty":2,"kind":"mc","stem":"고운 말이 아닌 것은 어느 것인가요?","options":[{"t":"「넌 원래 그래.」","correct":true},{"t":"「괜찮아.」","mis":"K2-1-u7-X18"},{"t":"「같이 하자.」","mis":"K2-1-u7-X18"}],"explanation":["「넌 원래 그래.」는 친구를 깎아내리는 말이에요.","「괜찮아.」와 「같이 하자.」는 고운 말이에요.","물음의 「아닌」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#2','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',2,'mc','auto','말을 할 때 먼저 생각해야 할 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X01']::text[],false,'{"seq":2,"concept":"K2-1-u7-C1","difficulty":2,"kind":"mc","stem":"말을 할 때 먼저 생각해야 할 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 말을 들을 사람의 마음","correct":true},{"t":"내가 지금 얼마나 화가 났는지","mis":"K2-1-u7-X12"},{"t":"말이 얼마나 긴지","mis":"K2-1-u7-X01"}],"explanation":["고운 말은 듣는 사람의 마음을 생각하는 데서 시작해요.","내 기분대로만 말하면 거친 말이 나오기 쉬워요.","말의 길이는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#3','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',3,'mc','auto','모둠 활동에서 한 친구가 자기 생각만 계속 말해요. 내 생각을 고운 말로 전한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":3,"concept":"K2-1-u7-C2","difficulty":3,"kind":"mc","stem":"모둠 활동에서 한 친구가 자기 생각만 계속 말해요. 내 생각을 고운 말로 전한 것은 어느 것인가요?","options":[{"t":"「네 생각도 좋다. 이번에는 내 생각도 들어 줄래?」","correct":true},{"t":"「너만 떠들지 마!」","mis":"K2-1-u7-X12"},{"t":"「응, 네 마음대로 다 해.」 하고 짜증 내기","mis":"K2-1-u7-X03"}],"explanation":["친구 생각을 인정하고 내 바람을 부탁하는 말로 전했어요.","「떠들지 마!」는 친구를 탓하는 거친 말이에요.","짜증 내며 비꼬는 말도 고운 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#4','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',3,'error','auto','거친 말을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],false,'{"seq":4,"concept":"K2-1-u7-C2","difficulty":3,"kind":"error","stem":"거친 말을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?","options":[{"t":"민준 — 「저리 비켜!」 → 「저리 좀 비켜 줄래, 느림보야?」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"아린 — 「시끄러워!」 → 「조금만 작게 말해 줄래?」","mis":"K2-1-u7-X18"},{"t":"지안 — 「내 거야!」 → 「이건 내 거라서 먼저 물어봐 줘.」","mis":"K2-1-u7-X18"}],"explanation":["부탁하는 말 끝에 「느림보야」를 붙이면 놀리는 말이 돼요.","아린이와 지안이는 바르게 바꾸었어요.","말 끝까지 다 고운지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#5','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',3,'ox','auto','친구에게 장난으로 한 놀리는 말은 친구가 웃고 있으면 괜찮아요.',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":5,"concept":"K2-1-u7-C1","difficulty":3,"kind":"ox","stem":"친구에게 장난으로 한 놀리는 말은 친구가 웃고 있으면 괜찮아요.","answer":"X","reason_options":[{"t":"겉으로 웃어도 속으로는 마음이 상했을 수 있으니까","correct":true},{"t":"웃고 있으면 마음도 언제나 기쁜 것이니까","mis":"K2-1-u7-X03"}],"mis":"K2-1-u7-X03","explanation":["웃는 얼굴 뒤에 속상한 마음이 있을 수 있어요.","장난이라도 놀리는 말은 거친 말이에요.","듣는 사람의 마음을 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#6','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',3,'mc','auto','동생이 내 책에 낙서를 했어요. 동생의 마음을 생각하며 고운 말로 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C2","difficulty":3,"kind":"mc","stem":"동생이 내 책에 낙서를 했어요. 동생의 마음을 생각하며 고운 말로 말한 것은 어느 것인가요?","options":[{"t":"「그림 그리고 싶었구나. 그래도 책 말고 이 종이에 그리자.」","correct":true},{"t":"「너 진짜 미워!」","mis":"K2-1-u7-X12"},{"t":"「낙서 잘했네!」","mis":"K2-1-u7-X02"}],"explanation":["동생의 마음을 알아주고 바라는 것을 부탁했어요.","「미워!」는 화난 기분만 쏟아 낸 말이에요.","칭찬할 일이 아니니 「잘했네!」는 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#7','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',3,'mc','auto','「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":7,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「문 좀 닫아 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「문 닫아!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 부탁하는 말이 더 고와요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#8','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',4,'mc','auto','친구가 내 자리에 앉아 있어서 수업 준비를 못 하고 있어요. 까닭과 바라는 것을 함께 담아 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":8,"concept":"K2-1-u7-C2","difficulty":4,"kind":"mc","stem":"친구가 내 자리에 앉아 있어서 수업 준비를 못 하고 있어요. 까닭과 바라는 것을 함께 담아 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「곧 수업이 시작돼서 준비해야 하거든. 자리를 비켜 줄 수 있니?」","correct":true},{"t":"「내 자리야, 당장 일어나!」","mis":"K2-1-u7-X12"},{"t":"「자리를 비켜 줄 수 있니? 넌 눈치도 없구나.」","mis":"K2-1-u7-X03"}],"explanation":["까닭을 말하고 부탁하는 말로 전했어요.","「당장 일어나!」는 명령하는 거친 말이에요.","부탁 뒤에 「눈치도 없구나」를 붙이면 비꼬는 말이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#9','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C2',4,'essay','teacher','내가 들었던 말 가운데 기분이 상했던 말을 하나 떠올려 쓰고, 그 말을 같은 뜻의 고운 말로 바꾸어 쓴 뒤 그렇게 바꾼 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":4,"kind":"essay","stem":"내가 들었던 말 가운데 기분이 상했던 말을 하나 떠올려 쓰고, 그 말을 같은 뜻의 고운 말로 바꾸어 쓴 뒤 그렇게 바꾼 까닭을 써 보세요.","answer_guide":{"answer":"예: 들었던 말 — 「너는 왜 맨날 늦어?」 바꾼 말 — 「무슨 일 있었니? 다음엔 같이 일찍 오자.」 까닭 — 늦은 까닭을 먼저 물어봐 주면 친구가 덜 속상하기 때문이에요.","scoring_points":["기분이 상했던 말을 썼는가","같은 뜻을 고운 말로 바꾸어 썼는가","듣는 사람의 마음을 생각해 바꾼 까닭을 썼는가"]},"explanation":["기분이 상했던 말.","고운 말로 바꾸기.","바꾼 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L01_challenge#10','kor',2,1,'u7','L01','g2_1_kor_u7_L01_challenge','lesson_challenge','K2-1-u7-C1',4,'essay','teacher','고운 말을 들어서 기분이 좋아졌던 경험을 떠올려 누가 어떤 말을 해 주었는지와 그때의 내 마음을 쓰고, 고운 말이 왜 필요한지 내 생각을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C1","difficulty":4,"kind":"essay","stem":"고운 말을 들어서 기분이 좋아졌던 경험을 떠올려 누가 어떤 말을 해 주었는지와 그때의 내 마음을 쓰고, 고운 말이 왜 필요한지 내 생각을 써 보세요.","answer_guide":{"answer":"예: 줄넘기 시험 날 짝이 「너는 할 수 있어!」라고 말해 주었어요. 그 말을 듣고 떨리던 마음이 든든해졌어요. 고운 말은 듣는 사람에게 힘을 주고 사이를 가깝게 해 주기 때문에 필요하다고 생각해요.","scoring_points":["누가 어떤 고운 말을 해 주었는지 썼는가","그때의 내 마음을 썼는가","고운 말이 필요한 까닭을 내 생각으로 썼는가"]},"explanation":["누가 어떤 말.","그때의 마음.","필요한 까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#1','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 서준이가 현관에 서 있던 까닭은 무엇인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":1,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이가 현관에 서 있던 까닭은 무엇인가요?","options":[{"t":"우산이 없어서","correct":true},{"t":"친구를 기다리려고","mis":"K2-1-u7-X04"},{"t":"신발을 잃어버려서","mis":"K2-1-u7-X04"}],"explanation":["서준이는 우산이 없어서 현관에 서 있었어요.","친구를 기다리거나 신발을 잃어버렸다는 말은 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 공원에서 연습한 것은 무엇인가요?","options":[{"t":"두발자전거 타기","correct":true},{"t":"줄넘기","mis":"K2-1-u7-X04"},{"t":"연날리기","mis":"K2-1-u7-X04"}],"explanation":["시우는 아빠와 두발자전거 타기를 연습했어요.","줄넘기와 연날리기는 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#2','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":2,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?","options":[{"t":"아린","correct":true},{"t":"서준","mis":"K2-1-u7-X05"},{"t":"선생님","mis":"K2-1-u7-X04"}],"explanation":["아린이가 「내 우산 같이 쓰자.」라고 말했어요.","서준이는 우산이 없던 인물이에요.","선생님은 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우의 자전거를 뒤에서 잡아 주겠다고 한 인물은 누구인가요?","options":[{"t":"아빠","correct":true},{"t":"시우","mis":"K2-1-u7-X05"},{"t":"형","mis":"K2-1-u7-X04"}],"explanation":["아빠가 「뒤에서 잡아 줄게.」라고 말했어요.","시우는 자전거를 배우던 인물이에요.","형은 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#3','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',1,'ox','auto','이야기를 읽고 답해 보세요. 서준이와 아린이는 우산 하나를 같이 쓰고 집까지 걸어갔어요.',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 서준이와 아린이는 우산 하나를 같이 쓰고 집까지 걸어갔어요.","answer":"O","reason_options":[{"t":"이야기에 둘이 우산을 나란히 쓰고 걸어갔다고 했으니까","correct":true},{"t":"아린이는 우산을 빌려주고 혼자 비를 맞았으니까","mis":"K2-1-u7-X04"}],"mis":"K2-1-u7-X04","explanation":["이야기에 둘이 우산 하나를 나란히 썼다고 했어요.","아린이가 비를 맞았다는 말은 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우는 처음부터 넘어지지 않고 자전거를 잘 탔어요.","answer":"X","reason_options":[{"t":"처음에는 기우뚱거리다 넘어져 무릎이 까졌다고 했으니까","correct":true},{"t":"시우는 자전거를 한 번도 연습하지 않았으니까","mis":"K2-1-u7-X04"}],"explanation":["처음에는 넘어져 무릎이 까졌어요.","몇 번을 더 연습해서 혼자 타게 되었어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#4','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',1,'mc','auto','이야기를 들을 때 비슷한 내 경험을 떠올리면 좋은 점은 무엇인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X07']::text[],true,'{"seq":4,"concept":"K2-1-u7-C4","difficulty":1,"kind":"mc","stem":"이야기를 들을 때 비슷한 내 경험을 떠올리면 좋은 점은 무엇인가요?","options":[{"t":"이야기가 더 잘 이해되고 재미있어져요","correct":true},{"t":"이야기를 끝까지 듣지 않아도 돼요","mis":"K2-1-u7-X04"},{"t":"인물의 이름을 바꿀 수 있어요","mis":"K2-1-u7-X07"}],"explanation":["내 경험과 이어 보면 인물의 마음이 더 잘 느껴져요.","이야기는 끝까지 잘 들어야 해요.","인물의 이름을 바꾸는 것과는 상관없어요."],"variant_rule":{"alt":[{"stem":"인물의 경험과 내 경험을 비교할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"인물과 내가 겪은 일과 그때의 마음","correct":true},{"t":"인물이 입은 옷의 색깔","mis":"K2-1-u7-X07"},{"t":"이야기의 글자 수","mis":"K2-1-u7-X07"}],"explanation":["겪은 일과 그때의 마음을 나란히 놓고 비교해요.","옷 색깔은 경험을 비교하는 데 필요 없어요.","글자 수는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#5','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'match','auto','이야기를 읽고 있었던 일과 그때의 마음을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C4","difficulty":2,"kind":"match","stem":"이야기를 읽고 있었던 일과 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"서준이가 우산 없이 서 있었다","r":"걱정스러웠다"},{"l":"서준이가 비를 안 맞고 집에 왔다","r":"고마웠다"},{"l":"아린이가 친구를 도왔다","r":"뿌듯했다"}],"mis":"K2-1-u7-X06","explanation":["우산이 없을 때는 걱정스러웠을 거예요.","비를 안 맞게 되어 고마웠어요.","아린이는 친구를 도와 뿌듯했어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 있었던 일과 그때의 마음을 알맞게 이어 보세요.","pairs":[{"l":"꽈당 넘어졌다","r":"아프고 속상했다"},{"l":"「나는 못 하겠어.」라고 했다","r":"그만두고 싶었다"},{"l":"혼자 자전거를 탔다","r":"하늘을 날 것처럼 기뻤다"}],"explanation":["넘어졌을 때는 아프고 속상했어요.","못 하겠다고 할 때는 그만두고 싶었어요.","혼자 탔을 때는 무척 기뻤어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#6','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],true,'{"seq":6,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"지우 — 「준비물을 안 가져왔을 때 짝이 빌려줘서 고마웠어.」","correct":true},{"t":"민호 — 「어제 저녁에 카레를 먹었어.」","mis":"K2-1-u7-X07"},{"t":"다은 — 「나는 비 오는 날을 좋아해.」","mis":"K2-1-u7-X07"}],"explanation":["서준이처럼 곤란할 때 친구의 도움을 받아 고마웠던 경험이에요.","저녁 반찬은 이야기와 상관없는 일이에요.","비를 좋아하는 것은 겪은 일이 아니라 좋아하는 것이에요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"하람 — 「수영을 처음 배울 때 무서웠는데 계속 연습해서 해냈어.」","correct":true},{"t":"채원 — 「내 자전거는 빨간색이야.」","mis":"K2-1-u7-X07"},{"t":"준우 — 「공원에는 비둘기가 많아.」","mis":"K2-1-u7-X07"}],"explanation":["처음엔 어려웠지만 연습해서 해낸 경험이 시우와 비슷해요.","자전거 색깔은 겪은 일이 아니에요.","공원의 비둘기는 이야기와 상관없어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#7','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',2,'mc','auto','이야기를 읽고 답해 보세요. 아린이가 우산을 같이 쓰자며 든 까닭은 무엇인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":7,"concept":"K2-1-u7-C3","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 아린이가 우산을 같이 쓰자며 든 까닭은 무엇인가요?","options":[{"t":"집이 같은 쪽이라서","correct":true},{"t":"우산이 두 개라서","mis":"K2-1-u7-X04"},{"t":"서준이가 빌려 달라고 부탁해서","mis":"K2-1-u7-X04"}],"explanation":["아린이는 「우리 집도 같은 쪽이야.」라고 했어요.","우산이 두 개라는 말은 없어요.","서준이가 부탁했다는 말도 없어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 아빠가 시우에게 해 준 말은 무엇인가요?","options":[{"t":"「괜찮아. 아빠가 뒤에서 잡아 줄게.」","correct":true},{"t":"「넘어지면 그만 타자.」","mis":"K2-1-u7-X04"},{"t":"「나는 못 하겠어.」","mis":"K2-1-u7-X05"}],"explanation":["아빠는 괜찮다며 뒤에서 잡아 주겠다고 했어요.","그만 타자는 말은 이야기에 없어요.","「나는 못 하겠어.」는 시우가 한 말이에요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#8','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C3',2,'sa','auto','이야기를 읽고 답해 보세요. 서준이가 아린이에게 한 고운 말을 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u7-C3","difficulty":2,"kind":"sa","stem":"이야기를 읽고 답해 보세요. 서준이가 아린이에게 한 고운 말을 세 글자로 써 보세요.","answer":["고마워"],"explanation":["서준이는 「고마워, 아린아.」라고 했어요.","도움을 받았을 때 하는 고운 말이에요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 넘어져서 다친 곳을 두 글자로 써 보세요.","answer":["무릎"],"explanation":["시우는 넘어져 무릎이 까졌어요.","처음에는 기우뚱거리다 넘어졌어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#9','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',2,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X18']::text[],true,'{"seq":9,"concept":"K2-1-u7-C4","difficulty":2,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"로아 — 「서준이처럼 나도 친구를 도와주고 뿌듯했어.」","correct":true,"mis_target":"K2-1-u7-X05"},{"t":"태민 — 「아린이처럼 나도 짐이 많은 할머니를 도와드리고 뿌듯했어.」","mis":"K2-1-u7-X18"},{"t":"윤호 — 「서준이처럼 나도 곤란할 때 친구가 도와줘서 고마웠어.」","mis":"K2-1-u7-X18"}],"explanation":["친구를 도와 뿌듯했던 인물은 서준이가 아니라 아린이에요.","태민이와 윤호는 인물을 바르게 짝 지었어요.","누가 한 일인지 이름에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"소율 — 「시우처럼 나도 처음부터 한 번에 줄넘기를 잘했어.」","correct":true,"mis_target":"K2-1-u7-X07"},{"t":"민준 — 「시우처럼 나도 줄넘기에 자꾸 걸렸지만 연습해서 해냈어.」","mis":"K2-1-u7-X18"},{"t":"서아 — 「시우 아빠처럼 언니도 내가 넘어졌을 때 괜찮다고 해 줬어.」","mis":"K2-1-u7-X18"}],"explanation":["시우는 처음에 넘어졌다가 연습해서 해냈어요.","처음부터 잘한 경험은 시우와 비슷하지 않아요.","민준이와 서아는 바르게 비교했어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_basic#10','kor',2,1,'u7','L03','g2_1_kor_u7_L03_basic','lesson_basic','K2-1-u7-C4',3,'mc','auto','이야기를 읽고 답해 보세요. 아린이의 마음과 가장 비슷한 마음이 들었을 경험은 어느 것인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X07']::text[],true,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 아린이의 마음과 가장 비슷한 마음이 들었을 경험은 어느 것인가요?","options":[{"t":"길을 묻는 할머니께 길을 알려 드렸을 때","correct":true},{"t":"비 오는 날 우산이 없어 곤란했을 때","mis":"K2-1-u7-X05"},{"t":"새 운동화를 샀을 때","mis":"K2-1-u7-X07"}],"explanation":["아린이는 친구를 도와 뿌듯했어요. 남을 도와드린 경험이 비슷해요.","우산이 없어 곤란했던 것은 서준이의 경험이에요.","새 운동화를 산 기쁨은 남을 도운 뿌듯함과 달라요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시우가 마지막에 느낀 마음과 가장 비슷한 마음이 들었을 경험은 어느 것인가요?","options":[{"t":"몇 번 실패한 끝에 혼자 신발 끈을 묶었을 때","correct":true},{"t":"넘어져 무릎이 까졌을 때","mis":"K2-1-u7-X04"},{"t":"동생과 장난감을 나눠 가졌을 때","mis":"K2-1-u7-X07"}],"explanation":["시우는 연습 끝에 해내서 무척 기뻤어요.","넘어졌을 때는 기쁨이 아니라 속상한 마음이었어요.","장난감을 나눈 일은 해낸 기쁨과 달라요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#1','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',2,'mc','auto','이야기를 읽고 답해 보세요. 일이 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":1,"concept":"K2-1-u7-C3","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 일이 일어난 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"비가 쏟아졌다 → 아린이가 같이 쓰자고 했다 → 둘이 함께 걸어갔다","correct":true},{"t":"아린이가 같이 쓰자고 했다 → 비가 쏟아졌다 → 둘이 함께 걸어갔다","mis":"K2-1-u7-X04"},{"t":"둘이 함께 걸어갔다 → 비가 쏟아졌다 → 서준이가 고맙다고 했다","mis":"K2-1-u7-X04"}],"explanation":["비가 쏟아진 뒤 아린이가 다가왔어요.","그다음 둘이 우산을 쓰고 걸어갔어요.","이야기의 차례를 손가락으로 짚어 확인해요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#2','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',2,'mc','auto','이야기를 읽고 답해 보세요. 시우가 혼자 자전거를 탈 수 있게 된 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":2,"concept":"K2-1-u7-C3","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우가 혼자 자전거를 탈 수 있게 된 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"넘어져도 포기하지 않고 몇 번을 더 연습해서","correct":true},{"t":"자전거를 새로 사서","mis":"K2-1-u7-X04"},{"t":"넘어진 뒤 바로 집에 가서","mis":"K2-1-u7-X04"}],"explanation":["몇 번을 더 연습하자 혼자 타게 되었어요.","자전거를 새로 샀다는 말은 없어요.","집에 갔다면 혼자 탈 수 없었을 거예요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#3','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',3,'mc','auto','이야기를 읽고 「나도 비슷한 경험이 있어.」라며 말했어요. 있었던 일과 그때의 마음을 모두 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X06','K2-1-u7-X07']::text[],false,'{"seq":3,"concept":"K2-1-u7-C4","difficulty":3,"kind":"mc","stem":"이야기를 읽고 「나도 비슷한 경험이 있어.」라며 말했어요. 있었던 일과 그때의 마음을 모두 말한 것은 어느 것인가요?","options":[{"t":"「나도 우산이 없을 때 짝이 같이 써 줘서 정말 고마웠어.」","correct":true},{"t":"「나도 우산이 없던 적이 있어.」","mis":"K2-1-u7-X06"},{"t":"「나는 비가 좋아.」","mis":"K2-1-u7-X07"}],"explanation":["있었던 일(짝이 우산을 같이 써 줌)과 마음(고마웠음)을 함께 말했어요.","있었던 일만 말하고 마음은 빠졌어요.","좋아하는 것은 겪은 일이 아니에요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#4','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',3,'error','auto','이야기를 읽고 내용을 말했어요. 이야기와 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X18']::text[],false,'{"seq":4,"concept":"K2-1-u7-C3","difficulty":3,"kind":"error","stem":"이야기를 읽고 내용을 말했어요. 이야기와 다르게 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「아빠가 자전거를 대신 타 주었어.」","correct":true,"mis_target":"K2-1-u7-X04"},{"t":"지호 — 「시우는 넘어져서 무릎이 까졌어.」","mis":"K2-1-u7-X18"},{"t":"예린 — 「아빠가 괜찮다고 하며 뒤에서 잡아 준다고 했어.」","mis":"K2-1-u7-X18"}],"explanation":["아빠가 자전거를 대신 탔다는 말은 이야기에 없어요.","지호와 예린이는 이야기와 같게 말했어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#5','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',3,'ox','auto','이야기 속 인물과 똑같은 일을 겪은 적이 없으면 비슷한 내 경험을 떠올릴 수 없어요.',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":5,"concept":"K2-1-u7-C4","difficulty":3,"kind":"ox","stem":"이야기 속 인물과 똑같은 일을 겪은 적이 없으면 비슷한 내 경험을 떠올릴 수 없어요.","answer":"X","reason_options":[{"t":"똑같은 일이 아니어도 비슷한 마음이 들었던 일을 떠올릴 수 있으니까","correct":true},{"t":"인물과 모든 것이 똑같아야 비슷한 경험이니까","mis":"K2-1-u7-X07"}],"mis":"K2-1-u7-X07","explanation":["우산을 같이 쓴 적이 없어도 도움을 받아 고마웠던 일은 떠올릴 수 있어요.","비슷한 마음이 들었던 일이면 비슷한 경험이에요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#6','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',3,'mc','auto','이야기를 읽고 답해 보세요. 「우두커니」는 서준이의 어떤 모습을 나타내나요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":6,"concept":"K2-1-u7-C3","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「우두커니」는 서준이의 어떤 모습을 나타내나요?","options":[{"t":"어찌할 바를 몰라 가만히 서 있는 모습","correct":true},{"t":"신나게 뛰어다니는 모습","mis":"K2-1-u7-X04"},{"t":"친구와 웃으며 이야기하는 모습","mis":"K2-1-u7-X04"}],"explanation":["우산이 없어 어찌할 바를 몰라 가만히 서 있었어요.","뛰어다녔다는 말은 없어요.","이때는 아직 아린이가 오기 전이에요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#7','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',3,'mc','auto','시우의 이야기를 듣고 떠올린 내 경험이에요. 「나는 지난봄에 처음 수영을 배웠어. 물이 코로 들어가서 무서웠어. 그래도 계속 연습해서 이제는 앞으로 갈 수 있어.」 여기에서 그때의 마음에 해당하는 것은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":7,"concept":"K2-1-u7-C4","difficulty":3,"kind":"mc","stem":"시우의 이야기를 듣고 떠올린 내 경험이에요. 「나는 지난봄에 처음 수영을 배웠어. 물이 코로 들어가서 무서웠어. 그래도 계속 연습해서 이제는 앞으로 갈 수 있어.」 여기에서 그때의 마음에 해당하는 것은 어느 것인가요?","options":[{"t":"무서웠어","correct":true},{"t":"처음 수영을 배웠어","mis":"K2-1-u7-X06"},{"t":"계속 연습했어","mis":"K2-1-u7-X06"}],"explanation":["「무서웠어」가 그때의 마음이에요.","「처음 수영을 배웠어」는 있었던 일이에요.","「계속 연습했어」도 한 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#8','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',4,'mc','auto','이야기를 읽고 답해 보세요. 서준이와 아린이의 마음을 바르게 짐작하고 내 경험과 이어 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":8,"concept":"K2-1-u7-C4","difficulty":4,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이와 아린이의 마음을 바르게 짐작하고 내 경험과 이어 말한 것은 어느 것인가요?","options":[{"t":"「서준이는 고맙고 아린이는 뿌듯했을 거야. 나도 동생 숙제를 도와줬을 때 아린이처럼 뿌듯했어.」","correct":true},{"t":"「서준이는 뿌듯하고 아린이는 고마웠을 거야. 나도 그랬어.」","mis":"K2-1-u7-X05"},{"t":"「둘 다 비를 맞아서 슬펐을 거야. 나도 비 맞은 적 있어.」","mis":"K2-1-u7-X04"}],"explanation":["두 인물의 마음을 바르게 짐작하고 비슷한 내 경험을 이었어요.","두 인물의 마음이 뒤바뀌었어요.","둘은 비를 맞지 않았어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#9','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C4',4,'essay','teacher','시우처럼 처음에는 어려웠지만 끝까지 해낸 내 경험을 떠올려 있었던 일과 그때의 마음을 쓰고, 시우의 경험과 비교해 같은 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C4","difficulty":4,"kind":"essay","stem":"시우처럼 처음에는 어려웠지만 끝까지 해낸 내 경험을 떠올려 있었던 일과 그때의 마음을 쓰고, 시우의 경험과 비교해 같은 점을 써 보세요.","answer_guide":{"answer":"예: 처음 줄넘기 2단 뛰기를 할 때 자꾸 줄에 걸려서 속상했어요. 날마다 연습했더니 마침내 성공해서 정말 기뻤어요. 시우처럼 처음엔 그만두고 싶었지만 포기하지 않고 연습해서 해낸 점이 같아요.","scoring_points":["있었던 일을 썼는가","그때의 마음을 썼는가","시우의 경험과 같은 점을 썼는가"]},"explanation":["있었던 일.","그때의 마음.","같은 점."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L03_challenge#10','kor',2,1,'u7','L03','g2_1_kor_u7_L03_challenge','lesson_challenge','K2-1-u7-C3',4,'essay','teacher','이야기를 읽고 답해 보세요. 내가 서준이라면 다음 날 아린이에게 어떤 고운 말을 더 해 주고 싶은지 쓰고, 그렇게 말하고 싶은 까닭을 이야기 내용을 들어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C3","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 내가 서준이라면 다음 날 아린이에게 어떤 고운 말을 더 해 주고 싶은지 쓰고, 그렇게 말하고 싶은 까닭을 이야기 내용을 들어 써 보세요.","answer_guide":{"answer":"예: 「어제 우산 같이 써 줘서 정말 고마웠어. 다음에 비 오면 이번엔 내가 같이 써 줄게.」 왜냐하면 아린이 덕분에 비를 하나도 안 맞고 집에 갈 수 있었기 때문이에요.","scoring_points":["아린이에게 할 고운 말을 썼는가","이야기 내용을 들어 까닭을 썼는가","이야기에 없는 내용을 지어내지 않았는가"]},"explanation":["고운 말.","이야기를 든 까닭.","이야기에 있는 내용."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#1','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":1,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?","options":[{"t":"지난 토요일","correct":true},{"t":"어제 저녁","mis":"K2-1-u7-X05"},{"t":"다음 주 일요일","mis":"K2-1-u7-X04"}],"explanation":["수빈이는 「지난 토요일에」 감자를 캤다고 했어요.","어제 저녁은 준우가 연을 날린 때예요.","다음 주 일요일은 발표에 없어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"},"variant_rule":{"alt":[{"stem":"발표를 읽고 답해 보세요. 준우가 연을 날린 곳은 어디인가요?","options":[{"t":"동네 공원","correct":true},{"t":"할머니 댁 텃밭","mis":"K2-1-u7-X05"},{"t":"바닷가","mis":"K2-1-u7-X04"}],"explanation":["준우는 「동네 공원에서」 연을 날렸다고 했어요.","할머니 댁 텃밭은 수빈이가 감자를 캔 곳이에요.","바닷가는 발표에 없어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#2','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C6',1,'mc','auto','발표할 때 바른 자세로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],true,'{"seq":2,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람을 골고루 바라보며 말해요","correct":true},{"t":"바닥만 보며 말해요","mis":"K2-1-u7-X10"},{"t":"몸을 이리저리 흔들며 말해요","mis":"K2-1-u7-X10"}],"explanation":["듣는 사람을 바라보면 내 말이 잘 전해져요.","바닥만 보면 목소리가 작아지고 마음이 전해지지 않아요.","몸을 흔들면 듣는 사람이 집중하기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"말끝까지 또박또박 말해요","correct":true},{"t":"말끝을 흐리며 작게 말해요","mis":"K2-1-u7-X10"},{"t":"발표 종이로 얼굴을 가리고 말해요","mis":"K2-1-u7-X10"}],"explanation":["말끝까지 또박또박 말해야 잘 들려요.","말끝을 흐리면 무슨 말인지 알기 어려워요.","얼굴을 가리면 목소리가 막혀요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#3','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',1,'ox','auto','경험을 발표할 때에는 한 일만 말하고 그때의 생각이나 느낌은 말하지 않아요.',ARRAY['K2-1-u7-X08']::text[],true,'{"seq":3,"concept":"K2-1-u7-C5","difficulty":1,"kind":"ox","stem":"경험을 발표할 때에는 한 일만 말하고 그때의 생각이나 느낌은 말하지 않아요.","answer":"X","reason_options":[{"t":"생각이나 느낌을 함께 말해야 경험이 잘 전해지니까","correct":true},{"t":"느낌은 듣는 사람에게 필요 없으니까","mis":"K2-1-u7-X08"}],"mis":"K2-1-u7-X08","explanation":["경험에는 겪은 일과 그때의 생각이나 느낌이 함께 들어가요.","느낌을 말하면 듣는 사람이 내 마음을 알 수 있어요.","언제 · 어디서 · 무슨 일 · 느낌을 확인해요."],"variant_rule":{"alt":[{"stem":"경험에는 내가 한 일, 본 일, 들은 일이 모두 들어갈 수 있어요.","answer":"O","reason_options":[{"t":"겪은 일은 한 일·본 일·들은 일을 모두 말하니까","correct":true},{"t":"경험에는 내가 한 일만 들어가니까","mis":"K2-1-u7-X08"}],"explanation":["본 일과 들은 일도 내 경험이에요.","그때의 생각이나 느낌도 함께 말해요.","언제 · 어디서 · 무슨 일 · 느낌을 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#4','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C6',1,'mc','auto','친구의 발표를 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],true,'{"seq":4,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"발표하는 친구를 바라보며 끝까지 들어요","correct":true},{"t":"짝과 이야기하며 들어요","mis":"K2-1-u7-X11"},{"t":"중간에 「틀렸어!」 하고 끼어들어요","mis":"K2-1-u7-X11"}],"explanation":["친구를 바라보며 끝까지 들으면 친구가 힘이 나요.","짝과 이야기하면 발표를 놓쳐요.","끼어들면 발표하는 친구가 당황해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"궁금한 것은 발표가 끝난 뒤 손을 들고 물어봐요","correct":true},{"t":"궁금하면 바로 소리쳐 물어봐요","mis":"K2-1-u7-X11"},{"t":"책상에 엎드려 들어요","mis":"K2-1-u7-X11"}],"explanation":["발표가 끝난 뒤 손을 들고 물어봐요.","중간에 소리치면 발표가 끊겨요.","엎드리면 친구가 잘 듣고 있는지 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#5','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'match','auto','발표를 읽고 발표 내용과 그 내용을 묻는 질문을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C5","difficulty":2,"kind":"match","stem":"발표를 읽고 발표 내용과 그 내용을 묻는 질문을 알맞게 이어 보세요.","pairs":[{"l":"지난 토요일","r":"언제?"},{"l":"할머니 댁 텃밭","r":"어디에서?"},{"l":"감자를 캤다","r":"무슨 일?"},{"l":"깜짝 놀랐다","r":"어떤 느낌?"}],"mis":"K2-1-u7-X09","explanation":["「지난 토요일」은 언제, 「할머니 댁 텃밭」은 어디에서예요.","「감자를 캤다」는 무슨 일이에요.","「깜짝 놀랐다」는 그때의 느낌이에요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표를 읽고 발표 내용과 그 내용을 묻는 질문을 알맞게 이어 보세요.","pairs":[{"l":"어제 저녁","r":"언제?"},{"l":"동네 공원","r":"어디에서?"},{"l":"연을 날렸다","r":"무슨 일?"},{"l":"정말 신났다","r":"어떤 느낌?"}],"explanation":["「어제 저녁」은 언제, 「동네 공원」은 어디에서예요.","「연을 날렸다」는 무슨 일이에요.","「정말 신났다」는 그때의 느낌이에요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#6','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],true,'{"seq":6,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"생각보다 감자가 많이 나와서 깜짝 놀랐어요.","correct":true},{"t":"저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","mis":"K2-1-u7-X06"},{"t":"호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","mis":"K2-1-u7-X06"}],"explanation":["「깜짝 놀랐어요」에 수빈이의 느낌이 드러나요.","언제·어디서 무슨 일을 했는지 말한 문장이에요.","감자를 캔 모습을 말한 문장이에요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"},"variant_rule":{"alt":[{"stem":"발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","correct":true},{"t":"저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","mis":"K2-1-u7-X06"},{"t":"바람이 세게 불자 연이 하늘 높이 올라갔어요.","mis":"K2-1-u7-X06"}],"explanation":["「정말 신났어요」에 준우의 느낌이 드러나요.","언제·어디서 무슨 일을 했는지 말한 문장이에요.","연이 올라간 모습을 말한 문장이에요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#7','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C6',2,'error','auto','발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?',ARRAY['K2-1-u7-X10','K2-1-u7-X18']::text[],true,'{"seq":7,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"지우 — 친구들을 보지 않고 창밖만 보며 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"윤호 — 모두에게 들리게 알맞은 크기로 말했어요.","mis":"K2-1-u7-X18"},{"t":"채원 — 바르게 서서 듣는 사람을 보며 말했어요.","mis":"K2-1-u7-X18"}],"explanation":["창밖만 보면 듣는 사람과 마음이 이어지지 않아요.","윤호와 채원이는 바르게 발표했어요.","듣는 사람을 바라보며 말해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 발표하는 모습이에요. 바르지 않게 발표한 친구는 누구인가요?","options":[{"t":"서준 — 너무 작은 목소리로 웅얼웅얼 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"아린 — 말끝까지 또박또박 분명하게 말했어요.","mis":"K2-1-u7-X18"},{"t":"하람 — 발표 전에 짝과 마주 보며 연습했어요.","mis":"K2-1-u7-X18"}],"explanation":["웅얼웅얼 작게 말하면 친구들이 듣기 어려워요.","아린이와 하람이는 바르게 했어요.","맨 뒤 친구도 들리게 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#8','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'mc','auto','경험을 발표하려고 내용을 정리할 때 들어갈 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"경험을 발표하려고 내용을 정리할 때 들어갈 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 전화번호","correct":true},{"t":"언제 있었던 일인지","mis":"K2-1-u7-X18"},{"t":"그때의 생각이나 느낌","mis":"K2-1-u7-X18"}],"explanation":["친구의 전화번호는 내 경험과 상관없어요.","언제와 그때의 느낌은 꼭 들어가야 해요.","물음의 「않은」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 경험을 발표하려고 내용을 정리할 때 들어갈 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"옆 반 친구의 받아쓰기 점수","correct":true},{"t":"어디에서 있었던 일인지","mis":"K2-1-u7-X18"},{"t":"무슨 일이 있었는지","mis":"K2-1-u7-X18"}],"explanation":["옆 반 친구의 점수는 내 경험과 상관없어요.","어디서·무슨 일은 꼭 들어가야 해요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#9','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',2,'blank','auto','발표를 읽고 답해 보세요. 준우의 발표를 짧게 정리했어요. 「준우는 (     ) 동네 공원에서 연을 날렸고, 정말 신났다.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":9,"concept":"K2-1-u7-C5","difficulty":2,"kind":"blank","stem":"발표를 읽고 답해 보세요. 준우의 발표를 짧게 정리했어요. 「준우는 (     ) 동네 공원에서 연을 날렸고, 정말 신났다.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"어제 저녁에","correct":true},{"t":"지난 토요일에","mis":"K2-1-u7-X05"},{"t":"다음 주에","mis":"K2-1-u7-X04"}],"explanation":["준우는 어제 저녁에 연을 날렸어요.","지난 토요일은 수빈이의 발표에 나온 때예요.","다음 주는 발표에 없어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"},"variant_rule":{"alt":[{"stem":"발표를 읽고 답해 보세요. 수빈이의 발표를 짧게 정리했어요. 「수빈이는 지난 토요일에 할머니 댁 텃밭에서 (     ) 깜짝 놀랐다.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"감자를 캐다가","correct":true},{"t":"연을 날리다가","mis":"K2-1-u7-X05"},{"t":"고구마를 심다가","mis":"K2-1-u7-X04"}],"explanation":["수빈이는 감자를 캐다가 감자가 많아 놀랐어요.","연날리기는 준우의 경험이에요.","고구마를 심었다는 말은 없어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_basic#10','kor',2,1,'u7','L05','g2_1_kor_u7_L05_basic','lesson_basic','K2-1-u7-C5',3,'mc','auto','「나는 놀이터에서 그네를 탔다. 미끄럼틀도 탔다. 시소도 탔다.」 이 발표에 더 넣으면 좋을 내용은 어느 것인가요?',ARRAY['K2-1-u7-X08']::text[],true,'{"seq":10,"concept":"K2-1-u7-C5","difficulty":3,"kind":"mc","stem":"「나는 놀이터에서 그네를 탔다. 미끄럼틀도 탔다. 시소도 탔다.」 이 발표에 더 넣으면 좋을 내용은 어느 것인가요?","options":[{"t":"언제 탔는지와 그때의 느낌","correct":true},{"t":"그네·미끄럼틀·시소를 또 탄 이야기","mis":"K2-1-u7-X08"},{"t":"놀이터 옆 가게의 이름","mis":"K2-1-u7-X08"}],"explanation":["언제와 그때의 느낌이 빠져 있어요.","한 일만 더 늘어놓으면 발표가 자세해지지 않아요.","가게 이름은 경험과 상관없어요."],"variant_rule":{"alt":[{"stem":"「나는 할머니 댁에 갔다. 재미있었다.」 이 발표를 더 자세하게 하려면 무엇을 더 넣으면 좋을까요?","options":[{"t":"언제 갔는지와 할머니 댁에서 무슨 일을 했는지","correct":true},{"t":"「재미있었다」를 세 번 더 말하기","mis":"K2-1-u7-X08"},{"t":"할머니 댁 전화번호","mis":"K2-1-u7-X08"}],"explanation":["언제와 무슨 일이 빠져 있어요.","같은 말을 되풀이한다고 자세해지지 않아요.","전화번호는 경험과 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#1','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',2,'mc','auto','발표하기 전에 하면 좋은 일은 어느 것인가요?',ARRAY['K2-1-u7-X08','K2-1-u7-X10']::text[],false,'{"seq":1,"concept":"K2-1-u7-C6","difficulty":2,"kind":"mc","stem":"발표하기 전에 하면 좋은 일은 어느 것인가요?","options":[{"t":"거울을 보거나 짝과 마주 보며 미리 연습해요","correct":true},{"t":"발표 내용을 하나도 정하지 않아요","mis":"K2-1-u7-X08"},{"t":"발표 종이로 얼굴을 가리는 연습을 해요","mis":"K2-1-u7-X10"}],"explanation":["미리 연습하면 자신 있게 발표할 수 있어요.","내용을 정하지 않으면 무엇을 말할지 몰라요.","얼굴을 가리면 목소리가 막혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#2','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 「다음에는 더 큰 연을 만들어 날리고 싶어요.」는 무엇을 말한 것인가요?',ARRAY['K2-1-u7-X09']::text[],false,'{"seq":2,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 「다음에는 더 큰 연을 만들어 날리고 싶어요.」는 무엇을 말한 것인가요?","options":[{"t":"앞으로 하고 싶은 생각","correct":true},{"t":"연을 날린 곳","mis":"K2-1-u7-X09"},{"t":"연을 날린 때","mis":"K2-1-u7-X09"}],"explanation":["앞으로 하고 싶은 생각을 말했어요.","연을 날린 곳은 「동네 공원」이에요.","연을 날린 때는 「어제 저녁」이에요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#3','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',3,'error','auto','발표를 읽고 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X18']::text[],false,'{"seq":3,"concept":"K2-1-u7-C5","difficulty":3,"kind":"error","stem":"발표를 읽고 내용을 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"민지 — 「어디에서: 수빈이네 집 마당」","correct":true,"mis_target":"K2-1-u7-X04"},{"t":"도담 — 「언제: 지난 토요일」","mis":"K2-1-u7-X18"},{"t":"현우 — 「느낌: 감자가 많이 나와 깜짝 놀랐다」","mis":"K2-1-u7-X18"}],"explanation":["수빈이는 할머니 댁 텃밭에서 감자를 캤어요.","도담이와 현우는 바르게 정리했어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#4','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',3,'mc','auto','발표할 때 알맞은 목소리 크기는 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],false,'{"seq":4,"concept":"K2-1-u7-C6","difficulty":3,"kind":"mc","stem":"발표할 때 알맞은 목소리 크기는 어느 것인가요?","options":[{"t":"교실 맨 뒤에 앉은 친구도 잘 들을 수 있는 크기","correct":true},{"t":"짝만 겨우 들을 수 있는 작은 소리","mis":"K2-1-u7-X10"},{"t":"옆 반까지 들릴 만큼 소리치는 소리","mis":"K2-1-u7-X10"}],"explanation":["맨 뒤 친구까지 들리면 모두가 들을 수 있어요.","너무 작으면 멀리 앉은 친구가 못 들어요.","소리치면 듣는 사람이 불편해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#5','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',3,'ox','auto','「저는 어제 학교에서 공부를 했어요.」만 말하면 경험을 자세하게 발표한 것이에요.',ARRAY['K2-1-u7-X08']::text[],false,'{"seq":5,"concept":"K2-1-u7-C5","difficulty":3,"kind":"ox","stem":"「저는 어제 학교에서 공부를 했어요.」만 말하면 경험을 자세하게 발표한 것이에요.","answer":"X","reason_options":[{"t":"무슨 공부를 했는지, 그때 어떤 느낌이었는지가 빠졌으니까","correct":true},{"t":"언제와 어디만 있으면 발표는 다 된 것이니까","mis":"K2-1-u7-X08"}],"mis":"K2-1-u7-X08","explanation":["무슨 일을 했는지 자세히 말하지 않았어요.","그때의 생각이나 느낌도 빠졌어요.","네 손가락을 꼽으며 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#6','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',3,'mc','auto','경험 발표의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X08']::text[],false,'{"seq":6,"concept":"K2-1-u7-C5","difficulty":3,"kind":"mc","stem":"경험 발표의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「처음으로 혼자 버스를 타 본 날」","correct":true},{"t":"「공룡의 종류」","mis":"K2-1-u7-X08"},{"t":"「내가 좋아하는 색깔」","mis":"K2-1-u7-X08"}],"explanation":["내가 직접 겪은 일이라 경험 발표에 알맞아요.","공룡의 종류는 겪은 일이 아니라 알려 주는 내용이에요.","좋아하는 색깔은 겪은 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#7','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',3,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 발표가 끝난 뒤 듣는 사람이 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],false,'{"seq":7,"concept":"K2-1-u7-C6","difficulty":3,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 발표가 끝난 뒤 듣는 사람이 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「감자가 줄줄이 나왔다니 신기하다. 캔 감자로 무엇을 해 먹었어?」","correct":true},{"t":"「그게 다야? 재미없어.」","mis":"K2-1-u7-X11"},{"t":"「나는 감자 싫어.」","mis":"K2-1-u7-X11"}],"explanation":["잘 들었다는 마음을 전하고 궁금한 점을 물었어요.","「재미없어」는 발표한 친구의 마음을 상하게 해요.","내가 싫어하는 것만 말하면 바르게 들은 게 아니에요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#8','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',4,'mc','auto','발표를 읽고 답해 보세요. 준우의 발표를 더 생생하게 고치려고 해요. 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K2-1-u7-X08']::text[],false,'{"seq":8,"concept":"K2-1-u7-C5","difficulty":4,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우의 발표를 더 생생하게 고치려고 해요. 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"연이 올라갈 때 무엇이 보였는지, 동생은 어떤 표정이었는지를 덧붙인다","correct":true},{"t":"「정말 신났어요」를 빼고 한 일만 남긴다","mis":"K2-1-u7-X08"},{"t":"연의 값이 얼마인지 덧붙인다","mis":"K2-1-u7-X08"}],"explanation":["본 일과 동생의 모습을 더하면 더 생생해져요.","느낌을 빼면 마음이 전해지지 않아요.","연의 값은 경험을 생생하게 하지 않아요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#9','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C5',4,'essay','teacher','기억에 남는 내 경험을 하나 골라, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"기억에 남는 내 경험을 하나 골라, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 저는 지난여름에 바닷가에서 가족과 모래성을 쌓았어요. 파도가 밀려와 모래성이 무너져서 아쉬웠지만 다시 쌓으니 더 크고 멋지게 되었어요. 다음에도 또 가고 싶어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L05_challenge#10','kor',2,1,'u7','L05','g2_1_kor_u7_L05_challenge','lesson_challenge','K2-1-u7-C6',4,'essay','teacher','친구가 발표할 때 바닥만 보고 작은 목소리로 말끝을 흐렸어요. 친구에게 도움이 되도록 바른 발표 자세를 두 가지 이상 고운 말로 알려 주는 말을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C6","difficulty":4,"kind":"essay","stem":"친구가 발표할 때 바닥만 보고 작은 목소리로 말끝을 흐렸어요. 친구에게 도움이 되도록 바른 발표 자세를 두 가지 이상 고운 말로 알려 주는 말을 써 보세요.","answer_guide":{"answer":"예: 「네 이야기 정말 재미있었어. 다음엔 우리를 바라보면서 조금만 더 크게, 말끝까지 또박또박 말해 주면 더 잘 들릴 것 같아. 나도 같이 연습해 줄게.」","scoring_points":["바른 발표 자세를 두 가지 이상 썼는가","친구의 마음을 생각한 고운 말로 썼는가","칭찬이나 응원을 함께 썼는가"]},"explanation":["바른 자세 두 가지.","고운 말.","칭찬이나 응원."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#1','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C7',1,'mc','auto','대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],true,'{"seq":1,"concept":"K2-1-u7-C7","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"깜짝 놀라고 속상했다","correct":true},{"t":"신나고 즐거웠다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯했다","mis":"K2-1-u7-X13"}],"explanation":["「앗」 하며 놀랐고 옷이 더러워져 속상했을 거예요.","옷에 우유가 튀어 신날 까닭이 없어요.","고맙거나 뿌듯할 일도 아니에요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 「왜 내 앞에 끼어드는 거야?」라고 말할 때 하람이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"억울하고 화가 났다","correct":true},{"t":"기쁘고 설렜다","mis":"K2-1-u7-X13"},{"t":"미안하고 부끄러웠다","mis":"K2-1-u7-X05"}],"explanation":["줄을 서 있는데 누가 앞에 끼어들어 억울했어요.","기쁠 까닭이 없어요.","미안한 마음은 이때 지호에게 더 어울려요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#2','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',1,'mc','auto','대화를 읽고 답해 보세요. 은솔이가 자기 잘못을 알고 한 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],true,'{"seq":2,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"대화를 읽고 답해 보세요. 은솔이가 자기 잘못을 알고 한 고운 말은 어느 것인가요?","options":[{"t":"「미안해.」","correct":true},{"t":"「고마워.」","mis":"K2-1-u7-X02"},{"t":"「축하해.」","mis":"K2-1-u7-X02"}],"explanation":["잘못했을 때는 「미안해.」라고 해요.","「고마워.」는 도움을 받았을 때 하는 말이에요.","「축하해.」는 기쁜 일에 하는 말이에요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 민지가 도움을 받고 한 고운 말은 어느 것인가요?","options":[{"t":"「고마워, 현우야.」","correct":true},{"t":"「미안해, 현우야.」","mis":"K2-1-u7-X02"},{"t":"「저리 가, 현우야.」","mis":"K2-1-u7-X03"}],"explanation":["도움을 받았을 때는 「고마워.」라고 해요.","「미안해.」는 잘못했을 때 하는 말이에요.","「저리 가」는 거친 말이에요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#3','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',1,'ox','auto','친구가 일부러 그런 것이 아닐 때에는 「괜찮아.」라고 말해 주면 좋아요.',ARRAY['K2-1-u7-X12']::text[],true,'{"seq":3,"concept":"K2-1-u7-C8","difficulty":1,"kind":"ox","stem":"친구가 일부러 그런 것이 아닐 때에는 「괜찮아.」라고 말해 주면 좋아요.","answer":"O","reason_options":[{"t":"친구의 미안한 마음을 헤아려 주는 말이니까","correct":true},{"t":"일부러 안 했어도 꼭 화를 내야 하니까","mis":"K2-1-u7-X12"}],"mis":"K2-1-u7-X12","explanation":["「괜찮아.」는 친구의 미안한 마음을 덜어 줘요.","일부러 한 일이 아니면 탓하지 않아요.","「일부러 그랬을까?」 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"내가 실수로 친구를 밀쳤을 때에는 모른 척하고 지나가요.","answer":"X","reason_options":[{"t":"「미안해. 괜찮아?」 하고 친구의 마음을 살펴야 하니까","correct":true},{"t":"일부러 민 게 아니면 말하지 않아도 되니까","mis":"K2-1-u7-X12"}],"explanation":["실수라도 친구는 아프고 놀랐을 수 있어요.","「미안해. 괜찮아?」 하고 살펴요.","친구의 마음을 먼저 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#4','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',1,'mc','auto','웃어른께 도움을 받았을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],true,'{"seq":4,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"웃어른께 도움을 받았을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「고맙습니다.」","correct":true},{"t":"「죄송합니다.」","mis":"K2-1-u7-X02"},{"t":"「안녕히 계세요.」","mis":"K2-1-u7-X02"}],"explanation":["도움을 받았을 때는 「고맙습니다.」라고 해요.","「죄송합니다.」는 잘못했을 때 하는 말이에요.","「안녕히 계세요.」는 헤어질 때 하는 인사예요."],"variant_rule":{"alt":[{"stem":"웃어른께 잘못을 했을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「죄송해요.」","correct":true},{"t":"「고맙습니다.」","mis":"K2-1-u7-X02"},{"t":"「축하해요.」","mis":"K2-1-u7-X02"}],"explanation":["잘못했을 때는 「죄송해요.」라고 해요.","「고맙습니다.」는 도움을 받았을 때 하는 말이에요.","「축하해요.」는 기쁜 일에 하는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#5','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',2,'match','auto','상황에 어울리는 고운 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C8","difficulty":2,"kind":"match","stem":"상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"물뿌리개가 무거워 힘든 친구","r":"내가 같이 들어 줄게."},{"l":"줄에 잘못 끼어든 나","r":"미안해, 뒤로 갈게."},{"l":"우유를 쏟아 당황한 친구","r":"괜찮아, 같이 닦자."}],"mis":"K2-1-u7-X02","explanation":["힘든 친구에게는 돕겠다고 해요.","잘못한 나는 사과하고 바로잡아요.","당황한 친구에게는 괜찮다고 해 줘요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"생일을 맞은 친구","r":"생일 축하해!"},{"l":"준비물을 빌려준 친구","r":"빌려줘서 고마워."},{"l":"발표를 앞두고 떨리는 친구","r":"천천히 하면 돼. 힘내!"}],"explanation":["기쁜 날에는 축하해요.","도움을 받으면 고맙다고 해요.","떨리는 친구에게는 힘을 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#6','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 지호가 줄에 끼어든 까닭은 무엇인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X04']::text[],true,'{"seq":6,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 지호가 줄에 끼어든 까닭은 무엇인가요?","options":[{"t":"줄이 어디까지인지 몰라서","correct":true},{"t":"하람이를 골탕 먹이려고","mis":"K2-1-u7-X12"},{"t":"줄 서기가 싫어서","mis":"K2-1-u7-X04"}],"explanation":["지호는 「줄이 여기까지인 줄 몰랐어.」라고 했어요.","일부러 골탕 먹이려 한 것이 아니에요.","줄 서기가 싫다는 말은 없어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 은솔이가 우유를 튀긴 까닭은 무엇인가요?","options":[{"t":"손이 미끄러져서","correct":true},{"t":"태민이를 골탕 먹이려고","mis":"K2-1-u7-X12"},{"t":"우유가 맛이 없어서","mis":"K2-1-u7-X04"}],"explanation":["은솔이는 「손이 미끄러졌어.」라고 했어요.","일부러 한 일이 아니에요.","우유 맛 이야기는 없어요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#7','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',2,'mc','auto','대화를 읽고 답해 보세요. 하람이가 마지막에 한 말이 고운 말인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],true,'{"seq":7,"concept":"K2-1-u7-C8","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하람이가 마지막에 한 말이 고운 말인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"지호의 마음을 헤아리고 자기 잘못도 사과했으니까","correct":true},{"t":"지호를 이겨서 기분이 좋으니까","mis":"K2-1-u7-X12"},{"t":"목소리를 크게 냈으니까","mis":"K2-1-u7-X03"}],"explanation":["「헷갈렸겠다」며 지호의 마음을 헤아렸어요.","큰 소리 낸 자기 잘못도 사과했어요.","이기고 지는 일이 아니에요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 태민이가 「괜찮아. 일부러 그런 거 아니잖아.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"은솔이가 일부러 그런 게 아님을 알고 미안한 마음을 헤아려서","correct":true},{"t":"옷에 우유가 튀어서 기뻐서","mis":"K2-1-u7-X13"},{"t":"은솔이에게 화를 내고 싶어서","mis":"K2-1-u7-X12"}],"explanation":["실수라는 것을 알고 은솔이의 마음을 헤아렸어요.","옷에 우유가 튀어 기쁠 까닭은 없어요.","화를 내고 싶었다면 「괜찮아.」라고 하지 않았을 거예요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#8','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',2,'error','auto','모둠 친구가 실수로 내 색종이를 찢었어요. 친구의 마음을 생각하지 않고 말한 친구는 누구인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C8","difficulty":2,"kind":"error","stem":"모둠 친구가 실수로 내 색종이를 찢었어요. 친구의 마음을 생각하지 않고 말한 친구는 누구인가요?","options":[{"t":"민준 — 「너 때문에 다 망쳤어! 저리 가!」","correct":true,"mis_target":"K2-1-u7-X12"},{"t":"서아 — 「괜찮아, 새 색종이로 다시 하자.」","mis":"K2-1-u7-X18"},{"t":"하윤 — 「일부러 그런 거 아니지? 같이 붙여 보자.」","mis":"K2-1-u7-X18"}],"explanation":["실수한 친구를 탓하며 화난 기분만 쏟아 냈어요.","서아와 하윤이는 친구의 마음을 생각했어요.","「일부러 그랬을까?」 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"친구가 달리다 내 발에 걸려 넘어졌어요. 친구의 마음을 생각하지 않고 말한 친구는 누구인가요?","options":[{"t":"지후 — 「하하, 왜 넘어지고 그래?」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"도담 — 「많이 아프지? 일어날 수 있겠어?」","mis":"K2-1-u7-X18"},{"t":"소율 — 「내 발에 걸렸구나, 미안해.」","mis":"K2-1-u7-X18"}],"explanation":["넘어진 친구를 비웃으면 마음이 더 아파요.","도담이와 소율이는 친구의 마음을 살폈어요.","내가 넘어졌다면 어땠을지 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#9','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 예린이가 「일부러 그런 거 아닌데…….」라고 말할 때의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],true,'{"seq":9,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 예린이가 「일부러 그런 거 아닌데…….」라고 말할 때의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"미안하면서도 억울하다","correct":true},{"t":"신나고 자랑스럽다","mis":"K2-1-u7-X13"},{"t":"블록 탑이 무너져 기쁘다","mis":"K2-1-u7-X13"}],"explanation":["탑을 무너뜨려 미안하지만 일부러가 아니라 억울했을 거예요.","자랑스러울 일이 아니에요.","탑이 무너져 기쁠 까닭이 없어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 도윤이가 「몰라, 저리 가!」라고 했을 때 예린이의 마음은 어떠했을까요?","options":[{"t":"서운하고 슬펐을 것이다","correct":true},{"t":"기쁘고 고마웠을 것이다","mis":"K2-1-u7-X13"},{"t":"뿌듯하고 즐거웠을 것이다","mis":"K2-1-u7-X13"}],"explanation":["사과하려던 예린이는 「저리 가!」를 듣고 서운했을 거예요.","기쁘거나 고마울 까닭이 없어요.","내가 예린이라면 어땠을지 생각해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_basic#10','kor',2,1,'u7','L07','g2_1_kor_u7_L07_basic','lesson_basic','K2-1-u7-C8',3,'mc','auto','대화를 읽고 답해 보세요. 도윤이가 예린이의 마음을 생각하며 고운 말로 다시 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],true,'{"seq":10,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이가 예린이의 마음을 생각하며 고운 말로 다시 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「탑이 무너져서 속상해. 그래도 일부러 그런 건 아니지? 같이 다시 쌓자.」","correct":true},{"t":"「몰라, 다시는 내 근처에 오지 마.」","mis":"K2-1-u7-X12"},{"t":"「탑을 무너뜨려 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["내 속상한 마음을 말하면서 예린이의 마음도 헤아렸어요.","더 거칠게 말하면 다툼이 커져요.","고마운 일이 아니니 「고마워.」는 맞지 않아요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]},"variant_rule":{"alt":[{"stem":"대화를 읽고 답해 보세요. 예린이가 도윤이의 마음을 생각하며 할 고운 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「열심히 쌓은 탑이 무너져서 속상하지? 미안해. 내가 같이 쌓아 줄게.」","correct":true},{"t":"「겨우 블록 가지고 왜 그래?」","mis":"K2-1-u7-X03"},{"t":"「축하해, 다시 쌓을 수 있겠다!」","mis":"K2-1-u7-X02"}],"explanation":["도윤이의 속상한 마음을 헤아리고 사과했어요.","「겨우 블록 가지고」는 도윤이의 마음을 무시하는 말이에요.","축하할 일이 아니에요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#1','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',2,'mc','auto','친구가 발표를 하다가 내용을 잊어버려 얼굴이 빨개졌어요. 친구의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":1,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"친구가 발표를 하다가 내용을 잊어버려 얼굴이 빨개졌어요. 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"당황스럽고 부끄럽다","correct":true},{"t":"자랑스럽고 신난다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯하다","mis":"K2-1-u7-X13"}],"explanation":["발표 중에 내용을 잊으면 당황스럽고 부끄러워요.","자랑스러울 상황이 아니에요.","내가 그 친구라면 어땠을지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#2','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',2,'mc','auto','친구의 마음을 생각하며 고운 말로 대화할 때 먼저 할 일은 어느 것인가요?',ARRAY['K2-1-u7-X12']::text[],false,'{"seq":2,"concept":"K2-1-u7-C8","difficulty":2,"kind":"mc","stem":"친구의 마음을 생각하며 고운 말로 대화할 때 먼저 할 일은 어느 것인가요?","options":[{"t":"친구가 지금 어떤 마음일지 생각해 본다","correct":true},{"t":"내가 하고 싶은 말을 바로 크게 말한다","mis":"K2-1-u7-X12"},{"t":"친구가 잘못한 점부터 찾는다","mis":"K2-1-u7-X12"}],"explanation":["마음을 먼저 생각하면 알맞은 고운 말이 떠올라요.","내 기분대로만 말하면 다투기 쉬워요.","잘못부터 따지면 친구가 속상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#3','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',3,'error','auto','대화를 읽고 친구들이 이야기를 나눴어요. 잘못 말한 친구는 누구인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X18']::text[],false,'{"seq":3,"concept":"K2-1-u7-C7","difficulty":3,"kind":"error","stem":"대화를 읽고 친구들이 이야기를 나눴어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「현우는 민지에게 미안해서 물뿌리개를 같이 들어 주었어.」","correct":true,"mis_target":"K2-1-u7-X04"},{"t":"채원 — 「민지는 물뿌리개가 무거워서 팔이 아팠어.」","mis":"K2-1-u7-X18"},{"t":"지안 — 「민지는 도움을 받고 고맙다고 말했어.」","mis":"K2-1-u7-X18"}],"explanation":["현우가 미안했다는 말은 대화에 없어요. 힘든 민지를 도와준 거예요.","채원이와 지안이는 대화와 같게 말했어요.","대화에서 그 말을 찾아 짚어요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#4','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',3,'mc','auto','쉬는 시간에 전학 온 친구가 혼자 앉아 있어요. 친구의 마음을 생각하며 한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X13']::text[],false,'{"seq":4,"concept":"K2-1-u7-C7","difficulty":3,"kind":"mc","stem":"쉬는 시간에 전학 온 친구가 혼자 앉아 있어요. 친구의 마음을 생각하며 한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우리랑 같이 놀래? 놀이 방법 알려 줄게.」","correct":true},{"t":"「왜 혼자 있어? 친구 없어?」","mis":"K2-1-u7-X03"},{"t":"「혼자 있는 게 좋은가 보네.」 하고 지나간다","mis":"K2-1-u7-X13"}],"explanation":["낯설어 외로울 친구의 마음을 헤아려 함께하자고 했어요.","「친구 없어?」는 친구의 마음을 아프게 해요.","혼자가 좋을 거라고 멋대로 짐작하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#5','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',3,'ox','auto','「미안해.」라는 말은 크게 잘못했을 때에만 하는 말이에요.',ARRAY['K2-1-u7-X12']::text[],false,'{"seq":5,"concept":"K2-1-u7-C8","difficulty":3,"kind":"ox","stem":"「미안해.」라는 말은 크게 잘못했을 때에만 하는 말이에요.","answer":"X","reason_options":[{"t":"작은 실수라도 상대가 불편했다면 미안하다고 말해야 하니까","correct":true},{"t":"작은 실수는 상대의 마음과 상관없으니까","mis":"K2-1-u7-X12"}],"mis":"K2-1-u7-X12","explanation":["작은 실수도 상대는 불편할 수 있어요.","「미안해.」 한마디가 마음을 풀어 줘요.","상대의 마음을 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#6','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',3,'mc','auto','대화를 읽고 답해 보세요. 은솔이의 말 「내가 휴지 가져다줄게.」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 은솔이의 말 「내가 휴지 가져다줄게.」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘못을 바로잡으려는 마음","correct":true},{"t":"태민이를 놀리려는 마음","mis":"K2-1-u7-X13"},{"t":"자기를 자랑하려는 마음","mis":"K2-1-u7-X13"}],"explanation":["사과에 그치지 않고 잘못을 바로잡으려 했어요.","놀리려는 마음은 대화에 드러나지 않아요.","자랑하려는 말이 아니에요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#7','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',3,'mc','auto','친구가 「네 덕분에 숙제를 끝냈어. 고마워!」라고 했어요. 대답할 고운 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X02']::text[],false,'{"seq":7,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 「네 덕분에 숙제를 끝냈어. 고마워!」라고 했어요. 대답할 고운 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「도움이 되었다니 나도 기뻐.」","correct":true},{"t":"「다음엔 너 혼자 해.」","mis":"K2-1-u7-X03"},{"t":"「미안해.」","mis":"K2-1-u7-X02"}],"explanation":["고맙다는 말에 기쁜 마음으로 대답했어요.","「너 혼자 해.」는 친구의 마음을 서운하게 해요.","잘못한 일이 없으니 「미안해.」는 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#8','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',4,'mc','auto','대화를 읽고 답해 보세요. 하람이와 지호의 대화가 다투지 않고 끝날 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X04']::text[],false,'{"seq":8,"concept":"K2-1-u7-C7","difficulty":4,"kind":"mc","stem":"대화를 읽고 답해 보세요. 하람이와 지호의 대화가 다투지 않고 끝날 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지호가 바로 사과하고, 하람이도 지호의 마음을 헤아려 자기 잘못을 사과해서","correct":true},{"t":"하람이가 큰 소리로 끝까지 따져서","mis":"K2-1-u7-X12"},{"t":"지호가 줄에서 빠져 집으로 가 버려서","mis":"K2-1-u7-X04"}],"explanation":["두 사람 모두 상대의 마음을 생각하며 고운 말로 대화했어요.","끝까지 따졌다면 다툼이 커졌을 거예요.","지호는 뒤로 가겠다고 했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#9','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C8',4,'essay','teacher','친구와 다툴 뻔했던 일을 하나 떠올려 그때 친구의 마음을 짐작해 쓰고, 친구의 마음을 생각하며 고운 말로 대화하는 장면을 두세 줄의 대화로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"친구와 다툴 뻔했던 일을 하나 떠올려 그때 친구의 마음을 짐작해 쓰고, 친구의 마음을 생각하며 고운 말로 대화하는 장면을 두세 줄의 대화로 써 보세요.","answer_guide":{"answer":"예: 짝이 내 필통을 떨어뜨렸어요. 짝은 당황하고 미안했을 거예요. 짝 — 「앗, 미안해. 내가 주워 줄게.」 나 — 「괜찮아, 일부러 그런 거 아니잖아. 같이 줍자.」","scoring_points":["다툴 뻔했던 일을 썼는가","친구의 마음을 짐작해 썼는가","상황에 맞는 고운 말로 대화를 썼는가"]},"explanation":["있었던 일.","친구의 마음.","고운 말 대화."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L07_challenge#10','kor',2,1,'u7','L07','g2_1_kor_u7_L07_challenge','lesson_challenge','K2-1-u7-C7',4,'essay','teacher','대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 각각 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 대화를 고쳐 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C7","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 각각 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 대화를 고쳐 써 보세요.","answer_guide":{"answer":"예: 도윤이는 열심히 쌓은 탑이 무너져 속상했고, 예린이는 미안하면서도 억울했을 거예요. 도윤 — 「탑이 무너져서 속상해.」 예린 — 「미안해. 일부러 그런 건 아니야. 같이 다시 쌓자.」 도윤 — 「그래, 같이 쌓자.」","scoring_points":["도윤이의 마음을 짐작해 썼는가","예린이의 마음을 짐작해 썼는가","두 사람이 고운 말로 대화하도록 고쳐 썼는가"]},"explanation":["도윤이의 마음.","예린이의 마음.","고운 말 대화."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#1','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',1,'mc','auto','이야기를 읽고 답해 보세요. 웅덩이에 빠진 도토리를 건져 준 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],true,'{"seq":1,"concept":"K2-1-u7-C9","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 웅덩이에 빠진 도토리를 건져 준 인물은 누구인가요?","options":[{"t":"거북 할아버지","correct":true},{"t":"토리","mis":"K2-1-u7-X05"},{"t":"토끼 아주머니","mis":"K2-1-u7-X04"}],"explanation":["거북 할아버지가 엉금엉금 다가와 건져 주었어요.","토리는 도토리를 빠뜨린 인물이에요.","토끼 아주머니는 이야기에 나오지 않아요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 나뭇가지에 걸린 풍선 줄을 잡아 준 인물은 누구인가요?","options":[{"t":"건우 형","correct":true},{"t":"하윤","mis":"K2-1-u7-X05"},{"t":"놀이공원 아저씨","mis":"K2-1-u7-X04"}],"explanation":["건우 형이 깡충 뛰어올라 잡아 주었어요.","하윤이는 풍선을 놓친 인물이에요.","놀이공원 아저씨는 풍선을 잡아 주지 않았어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#2','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',1,'mc','auto','이야기를 읽고 답해 보세요. 도토리가 웅덩이에 빠졌을 때 토리의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],true,'{"seq":2,"concept":"K2-1-u7-C9","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 도토리가 웅덩이에 빠졌을 때 토리의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"슬프고 속상했다","correct":true},{"t":"기쁘고 신났다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯했다","mis":"K2-1-u7-X13"}],"explanation":["토리는 엉엉 울었어요.","겨울에 먹으려고 모은 도토리라 더 속상했어요.","고마운 마음은 할아버지가 건져 준 뒤에 들었어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 풍선이 나뭇가지에 걸렸을 때 하윤이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"시무룩하고 속상했다","correct":true},{"t":"기쁘고 설렜다","mis":"K2-1-u7-X13"},{"t":"자랑스러웠다","mis":"K2-1-u7-X13"}],"explanation":["하윤이는 시무룩해졌어요.","풍선을 놓쳐 속상했어요.","기쁘거나 자랑스러울 까닭이 없어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#3','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',1,'ox','auto','고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.',ARRAY['K2-1-u7-X15']::text[],true,'{"seq":3,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.","answer":"X","reason_options":[{"t":"마음은 고운 말로 표현해야 상대에게 잘 전해지니까","correct":true},{"t":"마음은 말하지 않는 것이 더 고운 것이니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["말하지 않으면 상대는 내 마음을 모를 수 있어요.","「고마워.」 한마디로 마음이 전해져요.","누구에게 · 어떤 마음 · 왜를 담아 말해요."],"variant_rule":{"alt":[{"stem":"도움을 받으면 「고마워.」라고 말로 마음을 전하는 것이 좋아요.","answer":"O","reason_options":[{"t":"말로 전하면 도와준 사람의 마음도 따뜻해지니까","correct":true},{"t":"도와준 사람은 고맙다는 말을 싫어하니까","mis":"K2-1-u7-X15"}],"explanation":["고맙다는 말을 들으면 도와준 사람도 기뻐요.","마음은 말로 전해야 잘 알 수 있어요.","누구에게 · 어떤 마음 · 왜를 담아 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#4','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',1,'mc','auto','이야기를 읽고 답해 보세요. 거북 할아버지가 다가오는 모습을 흉내 낸 말은 어느 것인가요?',ARRAY['K2-1-u7-X14']::text[],true,'{"seq":4,"concept":"K2-1-u7-C9","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 거북 할아버지가 다가오는 모습을 흉내 낸 말은 어느 것인가요?","options":[{"t":"엉금엉금","correct":true},{"t":"데굴데굴","mis":"K2-1-u7-X14"},{"t":"퐁당","mis":"K2-1-u7-X14"}],"explanation":["「엉금엉금」은 느리게 기어가는 모양이에요.","「데굴데굴」은 도토리가 구르는 모양이에요.","「퐁당」은 물에 빠지는 소리예요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 풍선이 떠오르는 모습을 흉내 낸 말은 어느 것인가요?","options":[{"t":"둥실둥실","correct":true},{"t":"깡충","mis":"K2-1-u7-X14"},{"t":"생글생글","mis":"K2-1-u7-X14"}],"explanation":["「둥실둥실」은 가볍게 떠오르는 모양이에요.","「깡충」은 뛰어오르는 모양이에요.","「생글생글」은 웃는 모양이에요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#5','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"데굴데굴","r":"큰 물건이 계속 구르는 모양"},{"l":"퐁당","r":"작은 물건이 물에 떨어지는 소리"},{"l":"방긋","r":"소리 없이 살짝 웃는 모양"}],"mis":"K2-1-u7-X14","explanation":["도토리는 데굴데굴 굴렀어요.","도토리가 웅덩이에 퐁당 빠졌어요.","토리는 방긋 웃었어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"휙","r":"바람이 갑자기 세게 부는 소리"},{"l":"깡충","r":"가볍게 뛰어오르는 모양"},{"l":"생글생글","r":"눈과 입으로 귀엽게 웃는 모양"}],"explanation":["바람이 휙 불었어요.","건우 형이 깡충 뛰어올랐어요.","하윤이는 생글생글 웃었어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#6','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'mc','auto','이야기를 읽고 답해 보세요. 토리가 거북 할아버지께 도토리 과자를 드린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X02']::text[],true,'{"seq":6,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토리가 거북 할아버지께 도토리 과자를 드린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"도토리를 건져 주신 고마운 마음을 전하려고","correct":true},{"t":"도토리가 맛이 없어서","mis":"K2-1-u7-X04"},{"t":"할아버지께 잘못을 사과하려고","mis":"K2-1-u7-X02"}],"explanation":["도움을 받은 고마운 마음을 행동으로 전했어요.","도토리 맛 이야기는 없어요.","토리가 할아버지께 잘못한 일은 없어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 하윤이가 「이제 꼭 잡을게요.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"다시는 풍선을 놓치지 않겠다는 마음을 전하려고","correct":true},{"t":"건우 형에게 풍선을 주려고","mis":"K2-1-u7-X04"},{"t":"건우 형이 풍선을 놓쳤으니까","mis":"K2-1-u7-X05"}],"explanation":["도와준 형에게 고마움과 다짐을 함께 전했어요.","풍선을 준다는 말은 없어요.","풍선을 놓친 것은 하윤이예요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#7','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'mc','auto','쪽지를 읽고 답해 보세요. 서아가 지호에게 고마운 까닭은 무엇인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":7,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 서아가 지호에게 고마운 까닭은 무엇인가요?","options":[{"t":"필통을 놓고 왔을 때 연필을 빌려줘서","correct":true},{"t":"받아쓰기를 대신 해 줘서","mis":"K2-1-u7-X04"},{"t":"필통을 새로 사 줘서","mis":"K2-1-u7-X04"}],"explanation":["서아는 연필을 빌려준 일이 고마웠어요.","받아쓰기를 대신 했다는 말은 없어요.","필통을 사 줬다는 말도 없어요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"},"variant_rule":{"alt":[{"stem":"쪽지를 읽고 답해 보세요. 민호가 엄마께 죄송한 까닭은 무엇인가요?","options":[{"t":"아침에 짜증을 내서","correct":true},{"t":"학교에 가지 않아서","mis":"K2-1-u7-X04"},{"t":"엄마가 짜증을 내서","mis":"K2-1-u7-X05"}],"explanation":["민호는 아침에 짜증 낸 일이 죄송했어요.","학교에 가지 않았다는 말은 없어요.","짜증을 낸 사람은 엄마가 아니라 민호예요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#8','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'error','auto','고운 말로 마음을 전했어요. 마음에 어울리지 않는 말을 한 친구는 누구인가요?',ARRAY['K2-1-u7-X02','K2-1-u7-X18']::text[],true,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":2,"kind":"error","stem":"고운 말로 마음을 전했어요. 마음에 어울리지 않는 말을 한 친구는 누구인가요?","options":[{"t":"지안 — 동생 생일에 「동생아, 미안해!」","correct":true,"mis_target":"K2-1-u7-X02"},{"t":"윤서 — 짝이 도와줬을 때 「도와줘서 고마워.」","mis":"K2-1-u7-X18"},{"t":"하준 — 친구 발을 밟았을 때 「밟아서 미안해.」","mis":"K2-1-u7-X18"}],"explanation":["생일에는 「축하해!」라고 해야 어울려요.","윤서와 하준이는 마음에 맞는 말을 했어요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말로 마음을 전했어요. 마음에 어울리지 않는 말을 한 친구는 누구인가요?","options":[{"t":"태민 — 친구가 상을 받았을 때 「고마워!」","correct":true,"mis_target":"K2-1-u7-X02"},{"t":"은솔 — 친구가 상을 받았을 때 「상 받은 거 축하해!」","mis":"K2-1-u7-X18"},{"t":"민지 — 할머니가 반찬을 해 주셨을 때 「고맙습니다.」","mis":"K2-1-u7-X18"}],"explanation":["친구가 상을 받으면 「축하해!」라고 해요.","은솔이와 민지는 마음에 맞는 말을 했어요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#9','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C10',2,'mc','auto','쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15']::text[],true,'{"seq":9,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?","options":[{"t":"받는 사람: 지호 · 쓴 사람: 서아","correct":true},{"t":"받는 사람: 서아 · 쓴 사람: 지호","mis":"K2-1-u7-X15"},{"t":"받는 사람: 선생님 · 쓴 사람: 서아","mis":"K2-1-u7-X15"}],"explanation":["「지호에게」로 시작하니 받는 사람은 지호예요.","「— 서아가」로 끝나니 쓴 사람은 서아예요.","첫 줄과 끝 줄을 살펴요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?","options":[{"t":"받는 사람: 엄마 · 쓴 사람: 민호","correct":true},{"t":"받는 사람: 민호 · 쓴 사람: 엄마","mis":"K2-1-u7-X15"},{"t":"받는 사람: 아빠 · 쓴 사람: 민호","mis":"K2-1-u7-X15"}],"explanation":["「엄마께」로 시작하니 받는 사람은 엄마예요.","「— 민호 올림」으로 끝나니 쓴 사람은 민호예요.","첫 줄과 끝 줄을 살펴요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_basic#10','kor',2,1,'u7','L09','g2_1_kor_u7_L09_basic','lesson_basic','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],true,'{"seq":10,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"거북 할아버지가 도토리를 건져 주셔서","correct":true},{"t":"도토리를 웅덩이에 빠뜨려서","mis":"K2-1-u7-X04"},{"t":"할아버지께 도토리 과자를 받아서","mis":"K2-1-u7-X05"}],"explanation":["할아버지가 도토리를 건져 주자 토리가 웃었어요.","도토리를 빠뜨렸을 때는 울었어요.","과자는 토리가 할아버지께 드린 거예요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"},"variant_rule":{"alt":[{"stem":"이야기를 읽고 답해 보세요. 시무룩하던 하윤이가 생글생글 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"건우 형이 풍선 줄을 잡아 주어서","correct":true},{"t":"바람이 휙 불어서","mis":"K2-1-u7-X04"},{"t":"놀이공원에서 풍선을 받아서","mis":"K2-1-u7-X04"}],"explanation":["건우 형이 풍선 줄을 잡아 주자 하윤이가 웃었어요.","바람이 불어서 풍선을 놓쳤어요.","풍선을 받은 일은 이야기 처음에 있던 일이에요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#1','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',2,'mc','auto','마음 쪽지에 담기에 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":1,"concept":"K2-1-u7-C10","difficulty":2,"kind":"mc","stem":"마음 쪽지에 담기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 실수를 놀리는 말","correct":true},{"t":"도와줘서 고마운 마음","mis":"K2-1-u7-X18"},{"t":"잘못해서 미안한 마음","mis":"K2-1-u7-X18"}],"explanation":["놀리는 말은 마음을 아프게 해요.","고마운 마음과 미안한 마음은 쪽지에 담기 좋아요.","물음의 「않은」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#2','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',2,'mc','auto','이야기를 읽고 답해 보세요. 풍선 줄이 하윤이의 손에서 빠져나간 까닭은 무엇인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":2,"concept":"K2-1-u7-C9","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 풍선 줄이 하윤이의 손에서 빠져나간 까닭은 무엇인가요?","options":[{"t":"바람이 휙 불어서","correct":true},{"t":"건우 형이 잡아당겨서","mis":"K2-1-u7-X05"},{"t":"하윤이가 풍선을 버려서","mis":"K2-1-u7-X04"}],"explanation":["바람이 휙 불자 줄이 쏙 빠져나갔어요.","건우 형은 풍선을 잡아 준 인물이에요.","풍선을 버렸다는 말은 없어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#3','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 토리의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토리의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"즐겁다 → 슬프다 → 고맙다","correct":true},{"t":"슬프다 → 즐겁다 → 고맙다","mis":"K2-1-u7-X04"},{"t":"고맙다 → 슬프다 → 즐겁다","mis":"K2-1-u7-X04"}],"explanation":["도토리를 데굴데굴 굴리며 즐겁게 가다가 빠뜨려 슬펐어요.","할아버지가 건져 주자 고마웠어요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#4','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',3,'error','auto','이야기를 읽고 인물의 마음을 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?',ARRAY['K2-1-u7-X13','K2-1-u7-X18']::text[],false,'{"seq":4,"concept":"K2-1-u7-C9","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 마음을 짐작했어요. 알맞지 않게 짐작한 친구는 누구인가요?","options":[{"t":"현우 — 「건우 형은 풍선을 잡아 주기 싫었을 거야.」","correct":true,"mis_target":"K2-1-u7-X13"},{"t":"소율 — 「하윤이는 풍선을 놓쳐서 속상했을 거야.」","mis":"K2-1-u7-X18"},{"t":"예린 — 「건우 형은 하윤이가 웃어서 흐뭇했을 거야.」","mis":"K2-1-u7-X18"}],"explanation":["스스로 뛰어올라 잡아 준 형이 싫었을 리 없어요.","소율이와 예린이는 알맞게 짐작했어요.","그 인물이 되어 생각해 봐요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#5','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',3,'ox','auto','이야기를 읽고 답해 보세요. 「엉금엉금」은 거북 할아버지가 매우 빠르게 달려오는 모습을 나타내요.',ARRAY['K2-1-u7-X14']::text[],false,'{"seq":5,"concept":"K2-1-u7-C9","difficulty":3,"kind":"ox","stem":"이야기를 읽고 답해 보세요. 「엉금엉금」은 거북 할아버지가 매우 빠르게 달려오는 모습을 나타내요.","answer":"X","reason_options":[{"t":"「엉금엉금」은 느리게 기어가는 모양을 나타내니까","correct":true},{"t":"흉내 내는 말은 모두 빠른 모습을 나타내니까","mis":"K2-1-u7-X14"}],"mis":"K2-1-u7-X14","explanation":["「엉금엉금」은 느릿느릿 기어가는 모양이에요.","흉내 내는 말마다 나타내는 모양이 달라요.","몸짓으로 따라 해 봐요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#6','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',3,'mc','auto','친구에게 고마운 마음을 전하는 쪽지예요. 가장 잘 쓴 것은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X03']::text[],false,'{"seq":6,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"친구에게 고마운 마음을 전하는 쪽지예요. 가장 잘 쓴 것은 어느 것인가요?","options":[{"t":"「다은아, 내가 아플 때 알림장을 집에 가져다줘서 고마워. 덕분에 준비물을 챙길 수 있었어.」","correct":true},{"t":"「다은아, 고마워.」","mis":"K2-1-u7-X15"},{"t":"「다은아, 알림장 고마워. 근데 글씨가 엉망이더라.」","mis":"K2-1-u7-X03"}],"explanation":["받는 사람·고마운 일·덕분에 좋았던 점이 모두 담겼어요.","무엇이 고마운지 빠졌어요.","고마운 마음 뒤에 흉을 보면 마음이 상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#7','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 내용이 아닌 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":7,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 내용이 아닌 것은 어느 것인가요?","options":[{"t":"엄마께 선물을 사 드리겠다는 약속","correct":true},{"t":"짜증 낸 일에 대한 사과","mis":"K2-1-u7-X18"},{"t":"일찍 일어나겠다는 다짐","mis":"K2-1-u7-X18"}],"explanation":["선물 약속은 쪽지에 없어요.","사과와 다짐은 쪽지에 있어요.","물음의 「아닌」에 동그라미를 쳐요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#8','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',4,'mc','auto','이야기를 읽고 답해 보세요. 이 이야기를 읽고 떠올린 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X13']::text[],false,'{"seq":8,"concept":"K2-1-u7-C9","difficulty":4,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 이 이야기를 읽고 떠올린 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「곤란한 이웃을 도우면 서로 마음이 따뜻해지고, 고마운 마음은 말과 행동으로 전하면 좋겠어.」","correct":true},{"t":"「도토리는 굴리면 안 되는 열매야.」","mis":"K2-1-u7-X04"},{"t":"「거북은 느려서 아무도 못 도와.」","mis":"K2-1-u7-X13"}],"explanation":["도움을 주고받은 일과 고마움을 전한 일을 모두 담았어요.","도토리 굴리기는 이야기가 전하려는 생각이 아니에요.","거북 할아버지는 느려도 토리를 도왔어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#9','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C10',4,'essay','teacher','고마운 마음이나 미안한 마음을 전하고 싶은 사람을 한 명 떠올려, 받는 사람·전하고 싶은 마음·그 까닭이 드러나게 고운 말로 마음 쪽지를 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"고마운 마음이나 미안한 마음을 전하고 싶은 사람을 한 명 떠올려, 받는 사람·전하고 싶은 마음·그 까닭이 드러나게 고운 말로 마음 쪽지를 써 보세요.","answer_guide":{"answer":"예: 할머니께 — 할머니, 제가 감기에 걸렸을 때 따뜻한 죽을 끓여 주셔서 고맙습니다. 덕분에 빨리 나았어요. 다음에 할머니 댁에 가면 어깨를 주물러 드릴게요. — 지우 올림","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L09_challenge#10','kor',2,1,'u7','L09','g2_1_kor_u7_L09_challenge','lesson_challenge','K2-1-u7-C9',4,'essay','teacher','이야기를 읽고 답해 보세요. 하윤이의 마음이 어떻게 바뀌었는지 흉내 내는 말을 넣어 차례대로 쓰고, 내가 하윤이라면 건우 형에게 어떤 고운 말을 더 하고 싶은지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C9","difficulty":4,"kind":"essay","stem":"이야기를 읽고 답해 보세요. 하윤이의 마음이 어떻게 바뀌었는지 흉내 내는 말을 넣어 차례대로 쓰고, 내가 하윤이라면 건우 형에게 어떤 고운 말을 더 하고 싶은지 써 보세요.","answer_guide":{"answer":"예: 풍선을 놓쳐 시무룩했다가, 건우 형이 풍선을 잡아 주자 생글생글 웃을 만큼 기뻤어요. 「형 덕분에 풍선을 다시 찾았어요. 형도 놀이공원에서 즐겁게 놀아요!」","scoring_points":["마음이 바뀐 차례를 바르게 썼는가","흉내 내는 말을 알맞게 넣었는가","건우 형에게 할 고운 말을 썼는가"]},"explanation":["마음이 바뀐 차례.","흉내 내는 말.","고운 말."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#1','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 맞추기판에 있는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],true,'{"seq":1,"concept":"K2-1-u7-C11","difficulty":1,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 맞추기판에 있는 고운 말은 어느 것인가요?","options":[{"t":"걱정하지 마","correct":true},{"t":"시끄러워","mis":"K2-1-u7-X03"},{"t":"저리 가","mis":"K2-1-u7-X03"}],"explanation":["「걱정하지 마」는 셋째 줄에 있어요.","「시끄러워」와 「저리 가」는 거친 말이라 판에 없어요.","판에서 그 말을 찾아 짚어요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"},"variant_rule":{"alt":[{"stem":"맞추기판을 읽고 답해 보세요. 지안이의 맞추기판에 있는 고운 말은 어느 것인가요?","options":[{"t":"최고야","correct":true},{"t":"메롱","mis":"K2-1-u7-X03"},{"t":"비켜","mis":"K2-1-u7-X03"}],"explanation":["「최고야」는 셋째 줄에 있어요.","「메롱」과 「비켜」는 거친 말이라 판에 없어요.","판에서 그 말을 찾아 짚어요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#2','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'mc','auto','고운 말 맞추기판에 적기에 알맞지 않은 말은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],true,'{"seq":2,"concept":"K2-1-u7-C11","difficulty":1,"kind":"mc","stem":"고운 말 맞추기판에 적기에 알맞지 않은 말은 어느 것인가요?","options":[{"t":"넌 안 돼","correct":true},{"t":"같이 하자","mis":"K2-1-u7-X18"},{"t":"힘내","mis":"K2-1-u7-X18"}],"explanation":["「넌 안 돼」는 친구의 마음을 꺾는 말이에요.","「같이 하자」와 「힘내」는 고운 말이에요.","물음의 「않은」에 동그라미를 쳐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말 맞추기판에 적기에 알맞지 않은 말은 어느 것인가요?","options":[{"t":"바보야","correct":true},{"t":"잘했어","mis":"K2-1-u7-X18"},{"t":"고마워","mis":"K2-1-u7-X18"}],"explanation":["「바보야」는 친구를 놀리는 말이에요.","「잘했어」와 「고마워」는 고운 말이에요.","물음의 「않은」에 동그라미를 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#3','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'ox','auto','고운 말 맞추기 놀이는 친구가 말한 고운 말이 내 판에 있으면 표시하는 놀이예요.',ARRAY['K2-1-u7-X16']::text[],true,'{"seq":3,"concept":"K2-1-u7-C11","difficulty":1,"kind":"ox","stem":"고운 말 맞추기 놀이는 친구가 말한 고운 말이 내 판에 있으면 표시하는 놀이예요.","answer":"O","reason_options":[{"t":"친구가 말한 말과 같은 칸에 표시하며 고운 말을 익히니까","correct":true},{"t":"친구가 말한 말은 내 판에서 지워 버리는 놀이니까","mis":"K2-1-u7-X16"}],"mis":"K2-1-u7-X16","explanation":["친구가 말한 고운 말이 내 판에 있으면 표시해요.","표시한 칸이 세 줄이 되면 「맞았어!」 하고 외쳐요.","놀이하며 고운 말을 소리 내어 익혀요."],"variant_rule":{"alt":[{"stem":"고운 말은 놀이를 할 때만 쓰고 평소에는 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"놀이로 익힌 고운 말을 생활에서도 써야 하니까","correct":true},{"t":"고운 말은 놀이 규칙일 뿐이니까","mis":"K2-1-u7-X16"}],"explanation":["놀이는 고운 말을 익히는 연습이에요.","익힌 고운 말은 집과 학교에서 써요.","오늘 누구에게 쓸지 정해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#4','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',1,'mc','auto','줄넘기 대회에 나가는 친구에게 해 줄 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X02']::text[],true,'{"seq":4,"concept":"K2-1-u7-C11","difficulty":1,"kind":"mc","stem":"줄넘기 대회에 나가는 친구에게 해 줄 고운 말은 어느 것인가요?","options":[{"t":"「연습한 만큼 잘할 거야. 응원할게!」","correct":true},{"t":"「너는 떨어질 거야.」","mis":"K2-1-u7-X03"},{"t":"「미안해.」","mis":"K2-1-u7-X02"}],"explanation":["친구에게 힘을 주는 응원하는 말이에요.","「떨어질 거야」는 친구의 마음을 꺾는 말이에요.","잘못한 일이 없으니 「미안해.」는 맞지 않아요."],"variant_rule":{"alt":[{"stem":"새 옷을 입고 온 친구에게 해 줄 고운 말은 어느 것인가요?","options":[{"t":"「옷이 참 잘 어울린다!」","correct":true},{"t":"「그 옷 이상해.」","mis":"K2-1-u7-X03"},{"t":"「미안해.」","mis":"K2-1-u7-X02"}],"explanation":["친구를 기분 좋게 하는 칭찬하는 말이에요.","「이상해」는 친구의 마음을 상하게 해요.","잘못한 일이 없으니 「미안해.」는 맞지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#5','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'match','auto','상황에 어울리는 고운 말을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u7-C11","difficulty":2,"kind":"match","stem":"상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"함께 청소를 끝낸 친구","r":"같이 해서 금방 끝났다. 수고했어!"},{"l":"그림을 멋지게 완성한 친구","r":"색깔이 정말 멋지다!"},{"l":"약속에 늦어 사과하는 친구","r":"괜찮아, 무슨 일 있었어?"}],"mis":"K2-1-u7-X02","explanation":["함께 일한 친구에게는 수고했다고 해요.","잘한 친구에게는 칭찬해요.","사과하는 친구에게는 괜찮다고 하며 마음을 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 어울리는 고운 말을 알맞게 이어 보세요.","pairs":[{"l":"처음 인사하는 전학생","r":"반가워, 앞으로 친하게 지내자."},{"l":"공을 주워 준 친구","r":"공 주워 줘서 고마워."},{"l":"달리기에서 넘어진 친구","r":"끝까지 달려서 멋졌어."}],"explanation":["처음 만난 친구에게는 반갑게 맞아요.","도와준 친구에게는 고맙다고 해요.","넘어진 친구에게는 힘을 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#6','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 친구들이 「고마워」, 「미안해」, 「걱정하지 마」를 말해서 로아가 칸에 표시했어요. 표시한 칸이 이루는 줄은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],true,'{"seq":6,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 친구들이 「고마워」, 「미안해」, 「걱정하지 마」를 말해서 로아가 칸에 표시했어요. 표시한 칸이 이루는 줄은 어느 것인가요?","options":[{"t":"왼쪽 위에서 오른쪽 아래로 가는 대각선 한 줄","correct":true},{"t":"첫째 줄 가로 한 줄","mis":"K2-1-u7-X04"},{"t":"표시한 칸이 줄을 이루지 않아요","mis":"K2-1-u7-X04"}],"explanation":["「고마워」는 첫째 줄 첫째 칸, 「미안해」는 가운데 칸이에요.","「걱정하지 마」는 셋째 줄 마지막 칸이라 대각선이 돼요.","판에서 세 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"},"variant_rule":{"alt":[{"stem":"맞추기판을 읽고 답해 보세요. 친구들이 「축하해」, 「괜찮아?」, 「미안해」를 말해서 지안이가 칸에 표시했어요. 표시한 칸이 이루는 줄은 어느 것인가요?","options":[{"t":"맨 왼쪽 세로 한 줄","correct":true},{"t":"첫째 줄 가로 한 줄","mis":"K2-1-u7-X04"},{"t":"대각선 한 줄","mis":"K2-1-u7-X04"}],"explanation":["세 말은 모두 각 줄의 첫째 칸에 있어요.","그래서 맨 왼쪽 세로 한 줄이 돼요.","판에서 세 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#7','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'error','auto','고운 말 맞추기 놀이를 했어요. 놀이에서 지켜야 할 일을 지키지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],true,'{"seq":7,"concept":"K2-1-u7-C11","difficulty":2,"kind":"error","stem":"고운 말 맞추기 놀이를 했어요. 놀이에서 지켜야 할 일을 지키지 않은 친구는 누구인가요?","options":[{"t":"건우 — 친구가 말한 말이 자기 판에 없자 「그건 고운 말도 아니야!」 하고 소리쳤어요.","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"하늘 — 차례를 기다렸다가 「같이 하자」를 크게 말했어요.","mis":"K2-1-u7-X18"},{"t":"수빈 — 표시한 칸이 세 줄이 되자 「맞았어!」 하고 외쳤어요.","mis":"K2-1-u7-X18"}],"explanation":["고운 말 놀이에서 거친 말로 소리치면 안 돼요.","하늘이와 수빈이는 놀이 방법을 잘 지켰어요.","놀이할 때에도 고운 말을 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말 맞추기 놀이를 했어요. 놀이에서 지켜야 할 일을 지키지 않은 친구는 누구인가요?","options":[{"t":"서윤 — 판에 「메롱」을 적어 넣고 친구가 보자 키득키득 웃었어요.","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"도윤 — 좋아하는 고운 말 아홉 개를 판에 적었어요.","mis":"K2-1-u7-X18"},{"t":"로아 — 친구가 말한 고운 말이 판에 있어서 표시했어요.","mis":"K2-1-u7-X18"}],"explanation":["판에는 고운 말만 적어요. 「메롱」은 놀리는 말이에요.","도윤이와 로아는 놀이 방법을 잘 지켰어요.","놀이할 때에도 고운 말을 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#8','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'mc','auto','고운 말을 생활에서 실천한 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X16']::text[],true,'{"seq":8,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"고운 말을 생활에서 실천한 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"급식 당번에게 「맛있게 먹을게. 고마워.」라고 말했어요","correct":true},{"t":"동생이 블록을 쓰러뜨리자 「바보야!」라고 했어요","mis":"K2-1-u7-X03"},{"t":"고운 말은 공책에만 적고 말로는 하지 않았어요","mis":"K2-1-u7-X16"}],"explanation":["생활 속에서 고마운 마음을 고운 말로 전했어요.","「바보야!」는 거친 말이에요.","고운 말은 소리 내어 써야 마음이 전해져요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 고운 말을 생활에서 실천한 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"버스에서 내릴 때 기사님께 「고맙습니다.」 하고 인사했어요","correct":true},{"t":"친구가 실수하자 「그럴 줄 알았어.」라고 했어요","mis":"K2-1-u7-X03"},{"t":"놀이가 끝나자 다시 거친 말을 썼어요","mis":"K2-1-u7-X16"}],"explanation":["생활 속에서 고운 말을 썼어요.","「그럴 줄 알았어.」는 친구를 깎아내리는 말이에요.","놀이에서 익힌 고운 말을 계속 써야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#9','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',2,'blank','auto','친구가 내 이야기를 끝까지 들어 주었어요. 「내 이야기를 (     ) 고마워.」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],true,'{"seq":9,"concept":"K2-1-u7-C11","difficulty":2,"kind":"blank","stem":"친구가 내 이야기를 끝까지 들어 주었어요. 「내 이야기를 (     ) 고마워.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"들어 줘서","correct":true},{"t":"끊어 줘서","mis":"K2-1-u7-X03"},{"t":"놀려 줘서","mis":"K2-1-u7-X03"}],"explanation":["끝까지 들어 준 것이 고마운 일이에요.","이야기를 끊은 것은 고마운 일이 아니에요.","놀린 것도 고마운 일이 아니에요."],"variant_rule":{"alt":[{"stem":"친구가 다친 나를 보건실에 데려다주었어요. 「(     ) 덕분에 금방 나았어.」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"걱정해 줘서 고마워.","correct":true},{"t":"미안해, 잘못했어.","mis":"K2-1-u7-X02"},{"t":"생일 축하해.","mis":"K2-1-u7-X02"}],"explanation":["도움을 받았으니 고맙다고 해요.","잘못한 일이 아니니 사과할 까닭이 없어요.","생일과는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_basic#10','kor',2,1,'u7','L12','g2_1_kor_u7_L12_basic','lesson_basic','K2-1-u7-C11',3,'mc','auto','고운 말 맞추기 놀이를 한 뒤 느낀 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X16','K2-1-u7-X03']::text[],true,'{"seq":10,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"고운 말 맞추기 놀이를 한 뒤 느낀 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「고운 말을 크게 말하니 나도 듣는 친구도 기분이 좋아졌어. 집에서도 써 봐야지.」","correct":true},{"t":"「고운 말은 놀이에서만 쓰는 말이라 이제 안 써도 돼.」","mis":"K2-1-u7-X16"},{"t":"「줄만 먼저 만들면 돼. 말은 아무거나 괜찮아.」","mis":"K2-1-u7-X03"}],"explanation":["고운 말의 힘을 느끼고 생활에서 쓰겠다고 다짐했어요.","놀이가 끝나도 고운 말은 계속 써요.","놀이에서도 말은 고와야 해요."],"variant_rule":{"alt":[{"stem":"고운 말 맞추기판을 만들 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"들으면 기분이 좋아지는 고운 말을 내가 정한 칸에 하나씩 적는다","correct":true},{"t":"친구를 놀리는 재미있는 말도 섞어 적는다","mis":"K2-1-u7-X03"},{"t":"아홉 칸에 같은 말을 모두 적는다","mis":"K2-1-u7-X16"}],"explanation":["좋아하는 고운 말을 칸마다 하나씩 적어요.","놀리는 말은 판에 적지 않아요.","같은 말만 적으면 놀이를 할 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#1','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 맞추기판 한가운데 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":1,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 맞추기판 한가운데 칸에 있는 말은 어느 것인가요?","options":[{"t":"미안해","correct":true},{"t":"괜찮아","mis":"K2-1-u7-X04"},{"t":"넌 소중해","mis":"K2-1-u7-X04"}],"explanation":["한가운데 칸은 둘째 줄 가운데예요. 「미안해」가 있어요.","「괜찮아」는 첫째 줄 가운데에 있어요.","「넌 소중해」는 셋째 줄 가운데에 있어요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#2','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',2,'mc','auto','고운 말 맞추기판에 적을 말을 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X16','K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"고운 말 맞추기판에 적을 말을 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"들었을 때 마음이 따뜻해지는 말인가","correct":true},{"t":"글자 수가 가장 긴 말인가","mis":"K2-1-u7-X16"},{"t":"친구가 웃을 만큼 놀리는 말인가","mis":"K2-1-u7-X03"}],"explanation":["듣는 사람의 마음이 따뜻해지는 말을 골라요.","글자 수는 상관없어요.","놀리는 말은 고운 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#3','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'error','auto','같은 뜻을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X18']::text[],false,'{"seq":3,"concept":"K2-1-u7-C11","difficulty":3,"kind":"error","stem":"같은 뜻을 고운 말로 바꾸었어요. 잘못 바꾼 친구는 누구인가요?","options":[{"t":"아린 — 「빨리 해!」 → 「빨리 좀 해, 답답하게.」","correct":true,"mis_target":"K2-1-u7-X03"},{"t":"서준 — 「빨리 해!」 → 「조금만 서둘러 줄 수 있니?」","mis":"K2-1-u7-X18"},{"t":"지우 — 「이거 해!」 → 「이것 좀 도와줄래?」","mis":"K2-1-u7-X18"}],"explanation":["「답답하게」를 붙이면 여전히 탓하는 말이에요.","서준이와 지우는 부탁하는 말로 바르게 바꾸었어요.","말 끝까지 다 고운지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#4','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'mc','auto','친구가 「나는 그림을 못 그려.」 하며 풀이 죽어 있어요. 친구의 마음을 생각한 고운 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X03','K2-1-u7-X12']::text[],false,'{"seq":4,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"친구가 「나는 그림을 못 그려.」 하며 풀이 죽어 있어요. 친구의 마음을 생각한 고운 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「색칠을 꼼꼼하게 했네. 같이 그려 보자.」","correct":true},{"t":"「맞아, 진짜 못 그리긴 해.」","mis":"K2-1-u7-X03"},{"t":"「나는 잘 그리는데.」","mis":"K2-1-u7-X12"}],"explanation":["잘한 점을 찾아 칭찬하고 함께하자고 했어요.","친구의 말에 맞장구치며 흉보면 더 속상해요.","내 자랑만 하면 친구의 마음을 생각하지 않은 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#5','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'ox','auto','고운 말을 하면 듣는 사람뿐 아니라 말하는 나의 기분도 좋아질 수 있어요.',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":5,"concept":"K2-1-u7-C11","difficulty":3,"kind":"ox","stem":"고운 말을 하면 듣는 사람뿐 아니라 말하는 나의 기분도 좋아질 수 있어요.","answer":"O","reason_options":[{"t":"고운 말을 주고받으면 서로의 마음이 따뜻해지니까","correct":true},{"t":"고운 말은 듣는 사람에게만 좋은 말이니까","mis":"K2-1-u7-X01"}],"mis":"K2-1-u7-X01","explanation":["고운 말을 하면 내 마음도 밝아져요.","고운 말을 주고받으면 사이도 가까워져요.","오늘 쓸 고운 말을 정해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#6','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'mc','auto','맞추기판을 읽고 답해 보세요. 지안이의 판에 있는 말 가운데 넘어져 다친 친구에게 하기에 가장 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 지안이의 판에 있는 말 가운데 넘어져 다친 친구에게 하기에 가장 알맞은 말은 어느 것인가요?","options":[{"t":"괜찮아?","correct":true},{"t":"축하해","mis":"K2-1-u7-X02"},{"t":"최고야","mis":"K2-1-u7-X02"}],"explanation":["「괜찮아?」는 다친 친구의 마음을 살피는 말이에요.","「축하해」는 기쁜 일에 하는 말이에요.","「최고야」는 잘한 일을 칭찬하는 말이에요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#7','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',3,'mc','auto','고운 말을 실천하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K2-1-u7-X18']::text[],false,'{"seq":7,"concept":"K2-1-u7-C11","difficulty":3,"kind":"mc","stem":"고운 말을 실천하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"거친 말을 들으면 더 거친 말로 되갚아 준다","correct":true},{"t":"하루에 한 번 가족에게 고마운 점을 말한다","mis":"K2-1-u7-X18"},{"t":"친구가 잘한 점을 찾아 칭찬한다","mis":"K2-1-u7-X18"}],"explanation":["거친 말을 되갚으면 다툼이 커져요.","고마운 점 말하기와 칭찬하기는 좋은 실천이에요.","물음의 「않은」에 동그라미를 쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#8','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',4,'mc','auto','모둠 놀이에서 진 친구들이 「이건 반칙이야!」 하며 화를 냈어요. 이긴 모둠이 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":8,"concept":"K2-1-u7-C11","difficulty":4,"kind":"mc","stem":"모둠 놀이에서 진 친구들이 「이건 반칙이야!」 하며 화를 냈어요. 이긴 모둠이 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「다들 열심히 해서 재미있었어. 규칙이 헷갈렸다면 다음엔 같이 정해 보자.」","correct":true},{"t":"「졌으면서 왜 우겨? 너희가 못한 거야.」","mis":"K2-1-u7-X12"},{"t":"「우리가 이겼다! 메롱!」","mis":"K2-1-u7-X03"}],"explanation":["진 친구들의 속상한 마음을 헤아리고 함께 방법을 찾자고 했어요.","따지기만 하면 다툼이 커져요.","놀리면 진 친구들이 더 속상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#9','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',4,'essay','teacher','나만의 고운 말 맞추기판에 넣고 싶은 고운 말 세 가지를 쓰고, 각각 어떤 상황에서 누구에게 쓰면 좋을지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C11","difficulty":4,"kind":"essay","stem":"나만의 고운 말 맞추기판에 넣고 싶은 고운 말 세 가지를 쓰고, 각각 어떤 상황에서 누구에게 쓰면 좋을지 써 보세요.","answer_guide":{"answer":"예: 「고마워」 — 짝이 지우개를 빌려줄 때 짝에게. 「힘내」 — 동생이 받아쓰기를 걱정할 때 동생에게. 「같이 놀자」 — 혼자 있는 친구를 보았을 때 그 친구에게.","scoring_points":["고운 말을 세 가지 썼는가","각 말을 쓸 상황을 썼는가","상황에 어울리는 말을 골랐는가"]},"explanation":["고운 말 세 가지.","쓸 상황과 사람.","상황에 맞는 짝."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_L12_challenge#10','kor',2,1,'u7','L12','g2_1_kor_u7_L12_challenge','lesson_challenge','K2-1-u7-C11',4,'essay','teacher','일주일 동안 실천할 「고운 말 다짐」을 써 보세요. 누구에게, 어떤 상황에서, 어떤 고운 말을 쓸지와 그렇게 다짐한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u7-C11","difficulty":4,"kind":"essay","stem":"일주일 동안 실천할 「고운 말 다짐」을 써 보세요. 누구에게, 어떤 상황에서, 어떤 고운 말을 쓸지와 그렇게 다짐한 까닭을 써 보세요.","answer_guide":{"answer":"예: 나는 동생이 내 물건을 만질 때 「저리 가!」 대신 「쓰고 싶으면 먼저 말해 줘.」라고 말하겠어요. 왜냐하면 소리를 지르면 동생이 울고 우리 둘 다 기분이 나빠지기 때문이에요.","scoring_points":["누구에게 어떤 상황에서 쓸지 썼는가","쓸 고운 말을 썼는가","다짐한 까닭을 썼는가"]},"explanation":["누구에게·어떤 상황.","고운 말.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#1','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C1',1,'mc','auto','고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"고운 말을 써야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람의 마음을 따뜻하게 하니까","correct":true},{"t":"말을 빨리 끝낼 수 있으니까","mis":"K2-1-u7-X01"},{"t":"어른 앞에서만 지키면 되니까","mis":"K2-1-u7-X01"}],"explanation":["고운 말은 듣는 사람의 기분을 좋게 해요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#2','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「내가 도와줄게.」","correct":true},{"t":"「저리 비켜.」","mis":"K2-1-u7-X03"},{"t":"「그것도 못하니?」","mis":"K2-1-u7-X03"}],"explanation":["「내가 도와줄게.」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#3','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이에게 우산을 같이 쓰자고 한 인물은 누구인가요?","options":[{"t":"아린","correct":true},{"t":"서준","mis":"K2-1-u7-X05"},{"t":"선생님","mis":"K2-1-u7-X04"}],"explanation":["아린이가 「내 우산 같이 쓰자.」라고 했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#4','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이가 감자를 캔 때는 언제인가요?","options":[{"t":"지난 토요일","correct":true},{"t":"어제 저녁","mis":"K2-1-u7-X05"},{"t":"다음 주 일요일","mis":"K2-1-u7-X04"}],"explanation":["「지난 토요일에」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#5','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C6',1,'mc','auto','발표할 때 바른 자세로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람을 바라보며 말해요","correct":true},{"t":"바닥만 보며 말해요","mis":"K2-1-u7-X10"},{"t":"몸을 이리저리 흔들며 말해요","mis":"K2-1-u7-X10"}],"explanation":["듣는 사람을 바라보면 마음이 잘 전해져요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#6','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C8',1,'mc','auto','도움을 받았을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"도움을 받았을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「고마워.」","correct":true},{"t":"「미안해.」","mis":"K2-1-u7-X02"},{"t":"「축하해.」","mis":"K2-1-u7-X02"}],"explanation":["도움을 받으면 「고마워.」라고 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#7','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「어제 할머니 댁에 다녀온 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「어제 할머니 댁에 다녀온 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"어제 할머니 댁에 다녀왔어요.","correct":true},{"t":"어제 할머니 댁에 다녀온 것 같은 것 같아요.","mis":"K2-1-u7-X17"},{"t":"어제 할머니 댁에 다녀왔던 것 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「어제 할머니 댁에 다녀왔어요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#8','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C10',1,'ox','auto','고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"고마운 마음은 말로 전하지 않아도 상대가 저절로 알아요.","answer":"X","reason_options":[{"t":"마음은 고운 말로 표현해야 상대에게 잘 전해지니까","correct":true},{"t":"마음은 말하지 않는 것이 더 고운 것이니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["말하지 않으면 상대는 내 마음을 모를 수 있어요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#9','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"비켜!","r":"잠깐 지나가도 될까?"},{"l":"시끄러워!","r":"조금만 작게 말해 줄래?"},{"l":"그것도 몰라?","r":"내가 같이 알아볼게."}],"mis":"K2-1-u7-X02","explanation":["「비켜!」 → 「잠깐 지나가도 될까?」","「시끄러워!」 → 「조금만 작게 말해 줄래?」","「그것도 몰라?」 → 「내가 같이 알아볼게.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#10','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 서준이와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"지우 — 「준비물을 안 가져왔을 때 짝이 빌려줘서 고마웠어.」","correct":true},{"t":"민호 — 「어제 저녁에 카레를 먹었어.」","mis":"K2-1-u7-X07"},{"t":"다은 — 「나는 비 오는 날을 좋아해.」","mis":"K2-1-u7-X07"}],"explanation":["곤란할 때 도움을 받아 고마웠던 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#11','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"생각보다 감자가 많이 나와서 깜짝 놀랐어요.","correct":true},{"t":"저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","mis":"K2-1-u7-X06"},{"t":"호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","mis":"K2-1-u7-X06"}],"explanation":["「깜짝 놀랐어요」에 느낌이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#12','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 옷에 우유가 튀었을 때 태민이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"깜짝 놀라고 속상했다","correct":true},{"t":"신나고 즐거웠다","mis":"K2-1-u7-X13"},{"t":"고맙고 뿌듯했다","mis":"K2-1-u7-X13"}],"explanation":["옷이 더러워져 놀라고 속상했을 거예요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#13','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"데굴데굴","r":"큰 물건이 계속 구르는 모양"},{"l":"퐁당","r":"작은 물건이 물에 떨어지는 소리"},{"l":"엉금엉금","r":"느리게 기어가는 모양"}],"mis":"K2-1-u7-X14","explanation":["「데굴데굴」 — 큰 물건이 계속 구르는 모양","「퐁당」 — 작은 물건이 물에 떨어지는 소리","「엉금엉금」 — 느리게 기어가는 모양"],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#14','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"다녀온 것 같아요","r":"다녀왔어요"},{"l":"맛있었던 것 같아요","r":"맛있었어요"},{"l":"재미있는 것 같아요","r":"재미있어요"}],"mis":"K2-1-u7-X17","explanation":["「다녀온 것 같아요」 → 「다녀왔어요」","「맛있었던 것 같아요」 → 「맛있었어요」","「재미있는 것 같아요」 → 「재미있어요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#15','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 판 한가운데 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 판 한가운데 칸에 있는 말은 어느 것인가요?","options":[{"t":"미안해","correct":true},{"t":"괜찮아","mis":"K2-1-u7-X04"},{"t":"넌 소중해","mis":"K2-1-u7-X04"}],"explanation":["한가운데 칸은 둘째 줄 가운데예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#16','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C6',2,'error','auto','발표하는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X10','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표하는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"지우 — 친구들을 보지 않고 창밖만 보며 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"윤호 — 모두에게 들리게 알맞은 크기로 말했어요.","mis":"K2-1-u7-X18"},{"t":"채원 — 바르게 서서 듣는 사람을 보며 말했어요.","mis":"K2-1-u7-X18"}],"explanation":["창밖만 보면 마음이 전해지지 않아요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#17','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 실수로 내 블록 탑을 무너뜨렸어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 실수로 내 블록 탑을 무너뜨렸어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「탑이 무너져서 속상해. 일부러 그런 건 아니지? 같이 다시 쌓자.」","correct":true},{"t":"「몰라, 저리 가!」","mis":"K2-1-u7-X12"},{"t":"「무너뜨려 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["내 마음을 말하면서 친구의 마음도 헤아렸어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#18','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 엉엉 울던 토리가 방긋 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"거북 할아버지가 도토리를 건져 주셔서","correct":true},{"t":"도토리를 웅덩이에 빠뜨려서","mis":"K2-1-u7-X04"},{"t":"할아버지께 과자를 받아서","mis":"K2-1-u7-X05"}],"explanation":["할아버지가 도토리를 건져 주자 웃었어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#19','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 서아가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X04']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 서아가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"고마운 마음 — 연필을 빌려줘서","correct":true},{"t":"미안한 마음 — 연필을 빌려서","mis":"K2-1-u7-X15"},{"t":"고마운 마음 — 필통을 사 줘서","mis":"K2-1-u7-X04"}],"explanation":["연필을 빌려준 일이 고마웠어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#20','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"로아 — 「서준이처럼 나도 친구를 도와주고 뿌듯했어.」","correct":true,"mis_target":"K2-1-u7-X05"},{"t":"태민 — 「아린이처럼 나도 할머니를 도와드리고 뿌듯했어.」","mis":"K2-1-u7-X18"},{"t":"윤호 — 「서준이처럼 나도 친구가 도와줘서 고마웠어.」","mis":"K2-1-u7-X18"}],"explanation":["친구를 도와 뿌듯했던 인물은 아린이에요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#21','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C12',3,'ox','auto','「하늘에 먹구름이 끼어서 곧 비가 올 것 같아요.」는 알맞은 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「하늘에 먹구름이 끼어서 곧 비가 올 것 같아요.」는 알맞은 말이에요.","answer":"O","reason_options":[{"t":"아직 오지 않은 비를 짐작하는 말이니까","correct":true},{"t":"「것 같아요」는 언제나 틀린 말이니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["앞으로 일어날 일을 짐작할 때는 「것 같아요」를 써요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#22','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C1',3,'mc','auto','「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「문 닫아!」와 「문 좀 닫아 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「문 좀 닫아 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「문 닫아!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#23','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C5',4,'essay','teacher','가족과 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"가족과 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 지난 일요일에 집 앞 공원에서 가족과 배드민턴을 쳤어요. 아빠와 공을 스무 번 넘게 주고받아서 정말 신났어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#24','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 고쳐 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 도윤이와 예린이의 마음을 짐작해 쓰고, 두 사람이 고운 말로 다시 대화하도록 고쳐 써 보세요.","answer_guide":{"answer":"예: 도윤이는 속상하고 예린이는 미안했을 거예요. 도윤 — 「탑이 무너져서 속상해.」 예린 — 「미안해. 일부러 그런 건 아니야. 같이 다시 쌓자.」","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_a#25','kor',2,1,'u7','','g2_1_kor_u7_review_a','unit_review','K2-1-u7-C10',4,'essay','teacher','도움을 준 친구에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"도움을 준 친구에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 하준이에게 — 하준아, 내가 줄넘기를 잃어버렸을 때 같이 찾아 줘서 고마워. 덕분에 체육 시간에 줄넘기를 할 수 있었어. — 서윤이가","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#1','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C1',1,'mc','auto','거친 말을 자주 들은 친구에게 생길 수 있는 일은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"거친 말을 자주 들은 친구에게 생길 수 있는 일은 어느 것인가요?","options":[{"t":"마음이 상해 말한 사람과 멀어진다","correct":true},{"t":"기분이 좋아져 더 친해진다","mis":"K2-1-u7-X01"},{"t":"아무 느낌이 없다","mis":"K2-1-u7-X01"}],"explanation":["거친 말은 마음을 아프게 하고 사이를 멀게 해요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#2','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「같이 하자.」","correct":true},{"t":"「시끄러워.」","mis":"K2-1-u7-X03"},{"t":"「바보야.」","mis":"K2-1-u7-X03"}],"explanation":["「같이 하자.」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#3','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 시우의 자전거를 뒤에서 잡아 주겠다고 한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우의 자전거를 뒤에서 잡아 주겠다고 한 인물은 누구인가요?","options":[{"t":"아빠","correct":true},{"t":"시우","mis":"K2-1-u7-X05"},{"t":"형","mis":"K2-1-u7-X04"}],"explanation":["아빠가 「뒤에서 잡아 줄게.」라고 했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#4','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 준우가 연을 날린 곳은 어디인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우가 연을 날린 곳은 어디인가요?","options":[{"t":"동네 공원","correct":true},{"t":"할머니 댁 텃밭","mis":"K2-1-u7-X05"},{"t":"바닷가","mis":"K2-1-u7-X04"}],"explanation":["「동네 공원에서」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#5','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C6',1,'mc','auto','발표할 때 바른 자세로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X10']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"발표할 때 바른 자세로 알맞은 것은 어느 것인가요?","options":[{"t":"말끝까지 또박또박 말해요","correct":true},{"t":"말끝을 흐리며 말해요","mis":"K2-1-u7-X10"},{"t":"종이로 얼굴을 가리고 말해요","mis":"K2-1-u7-X10"}],"explanation":["말끝까지 또박또박 말해야 잘 들려요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#6','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',1,'mc','auto','잘못했을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"잘못했을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「미안해.」","correct":true},{"t":"「고마워.」","mis":"K2-1-u7-X02"},{"t":"「잘했어.」","mis":"K2-1-u7-X02"}],"explanation":["잘못했을 때는 「미안해.」라고 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#7','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「오늘 아침에 밥을 먹은 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「오늘 아침에 밥을 먹은 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"오늘 아침에 밥을 먹었어요.","correct":true},{"t":"오늘 아침에 밥을 먹었던 것 같아요.","mis":"K2-1-u7-X17"},{"t":"오늘 아침에 밥을 먹은 것도 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「오늘 아침에 밥을 먹었어요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#8','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C10',1,'ox','auto','도움을 받으면 「고마워.」라고 말로 마음을 전하는 것이 좋아요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"도움을 받으면 「고마워.」라고 말로 마음을 전하는 것이 좋아요.","answer":"O","reason_options":[{"t":"말로 전하면 도와준 사람의 마음도 따뜻해지니까","correct":true},{"t":"도와준 사람은 고맙다는 말을 싫어하니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["고맙다는 말을 들으면 도와준 사람도 기뻐요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#9','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"내 거 만지지 마!","r":"쓰기 전에 먼저 물어봐 줄래?"},{"l":"느림보야!","r":"천천히 해도 괜찮아."},{"l":"너 때문이야!","r":"같이 방법을 찾아보자."}],"mis":"K2-1-u7-X02","explanation":["「내 거 만지지 마!」 → 「쓰기 전에 먼저 물어봐 줄래?」","「느림보야!」 → 「천천히 해도 괜찮아.」","「너 때문이야!」 → 「같이 방법을 찾아보자.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#10','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"하람 — 「수영을 처음 배울 때 무서웠는데 연습해서 해냈어.」","correct":true},{"t":"채원 — 「내 자전거는 빨간색이야.」","mis":"K2-1-u7-X07"},{"t":"준우 — 「공원에는 비둘기가 많아.」","mis":"K2-1-u7-X07"}],"explanation":["어려웠지만 연습해서 해낸 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#11','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","correct":true},{"t":"저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","mis":"K2-1-u7-X06"},{"t":"바람이 세게 불자 연이 하늘 높이 올라갔어요.","mis":"K2-1-u7-X06"}],"explanation":["「정말 신났어요」에 느낌이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#12','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 「왜 내 앞에 끼어드는 거야?」라고 말할 때 하람이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13','K2-1-u7-X05']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 「왜 내 앞에 끼어드는 거야?」라고 말할 때 하람이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"억울하고 화가 났다","correct":true},{"t":"기쁘고 설렜다","mis":"K2-1-u7-X13"},{"t":"미안하고 부끄러웠다","mis":"K2-1-u7-X05"}],"explanation":["줄을 서 있는데 누가 끼어들어 억울했어요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#13','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"휙","r":"바람이 갑자기 세게 부는 소리"},{"l":"둥실둥실","r":"가볍게 떠오르는 모양"},{"l":"깡충","r":"가볍게 뛰어오르는 모양"}],"mis":"K2-1-u7-X14","explanation":["「휙」 — 바람이 갑자기 세게 부는 소리","「둥실둥실」 — 가볍게 떠오르는 모양","「깡충」 — 가볍게 뛰어오르는 모양"],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#14','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"먹은 것 같아요","r":"먹었어요"},{"l":"신났던 것 같아요","r":"신났어요"},{"l":"예쁜 것 같아요","r":"예뻐요"}],"mis":"K2-1-u7-X17","explanation":["「먹은 것 같아요」 → 「먹었어요」","「신났던 것 같아요」 → 「신났어요」","「예쁜 것 같아요」 → 「예뻐요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#15','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 지안이의 판 한가운데 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 지안이의 판 한가운데 칸에 있는 말은 어느 것인가요?","options":[{"t":"같이 놀자","correct":true},{"t":"멋지다","mis":"K2-1-u7-X04"},{"t":"힘내","mis":"K2-1-u7-X04"}],"explanation":["한가운데 칸은 둘째 줄 가운데예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#16','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C6',2,'error','auto','발표하는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X10','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표하는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"서준 — 너무 작은 목소리로 웅얼웅얼 말했어요.","correct":true,"mis_target":"K2-1-u7-X10"},{"t":"아린 — 말끝까지 또박또박 말했어요.","mis":"K2-1-u7-X18"},{"t":"하람 — 듣는 사람을 골고루 바라보며 말했어요.","mis":"K2-1-u7-X18"}],"explanation":["웅얼웅얼 말하면 듣기 어려워요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#17','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 실수로 내 옷에 우유를 튀겼어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 실수로 내 옷에 우유를 튀겼어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「괜찮아. 일부러 그런 거 아니잖아. 같이 닦자.」","correct":true},{"t":"「너 때문에 옷 다 버렸잖아!」","mis":"K2-1-u7-X12"},{"t":"「축하해!」","mis":"K2-1-u7-X02"}],"explanation":["실수한 친구의 미안한 마음을 헤아렸어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#18','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 시무룩하던 하윤이가 생글생글 웃게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시무룩하던 하윤이가 생글생글 웃게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"건우 형이 풍선 줄을 잡아 주어서","correct":true},{"t":"바람이 휙 불어서","mis":"K2-1-u7-X04"},{"t":"건우 형에게 풍선을 주어서","mis":"K2-1-u7-X05"}],"explanation":["형이 풍선을 잡아 주자 웃었어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#19','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X04']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 민호가 쪽지에 담은 마음과 그 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"죄송한 마음 — 아침에 짜증을 내서","correct":true},{"t":"고마운 마음 — 아침에 짜증을 내서","mis":"K2-1-u7-X15"},{"t":"죄송한 마음 — 학교에 늦어서","mis":"K2-1-u7-X04"}],"explanation":["짜증 낸 일이 죄송했어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#20','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X07','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"소율 — 「시우처럼 나도 처음부터 한 번에 줄넘기를 잘했어.」","correct":true,"mis_target":"K2-1-u7-X07"},{"t":"민준 — 「시우처럼 나도 자꾸 걸렸지만 연습해서 해냈어.」","mis":"K2-1-u7-X18"},{"t":"서아 — 「시우 아빠처럼 언니도 나를 응원해 줬어.」","mis":"K2-1-u7-X18"}],"explanation":["시우는 처음에 넘어졌다가 연습해서 해냈어요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#21','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C12',3,'ox','auto','「오늘 급식에 나온 김치를 먹은 것 같아요.」는 또렷한 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「오늘 급식에 나온 김치를 먹은 것 같아요.」는 또렷한 말이에요.","answer":"X","reason_options":[{"t":"내가 직접 먹은 일이니 「먹었어요.」라고 해야 하니까","correct":true},{"t":"「것 같아요」를 붙여야 예의 바른 말이니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["직접 한 일은 「먹었어요.」처럼 또렷하게 말해요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#22','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C1',3,'mc','auto','「비켜!」와 「잠깐 지나가도 될까?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「비켜!」와 「잠깐 지나가도 될까?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「잠깐 지나가도 될까?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「비켜!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#23','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C5',4,'essay','teacher','처음 해 본 일 가운데 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"처음 해 본 일 가운데 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 지난주 토요일에 우리 집 부엌에서 처음으로 달걀 프라이를 만들었어요. 기름이 튀어 무서웠지만 다 만들고 나니 뿌듯했어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#24','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 은솔이가 사과했을 때 태민이가 화를 냈다면 어떻게 되었을지 쓰고, 태민이의 고운 말이 왜 좋았는지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 은솔이가 사과했을 때 태민이가 화를 냈다면 어떻게 되었을지 쓰고, 태민이의 고운 말이 왜 좋았는지 써 보세요.","answer_guide":{"answer":"예: 태민이가 화를 냈다면 은솔이는 더 미안하고 속상해서 둘이 다투었을 거예요. 태민이가 「괜찮아. 같이 닦자.」라고 해서 은솔이의 마음이 풀리고 함께 문제를 해결할 수 있었어요.","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"태민","text":"앗, 내 옷에 우유가 튀었잖아!"},{"who":"은솔","text":"어머, 미안해. 손이 미끄러졌어. 내가 휴지 가져다줄게."},{"who":"태민","text":"괜찮아. 일부러 그런 거 아니잖아. 같이 닦자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_b#25','kor',2,1,'u7','','g2_1_kor_u7_review_b','unit_review','K2-1-u7-C10',4,'essay','teacher','가족에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"가족에게 고마운 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 아빠께 — 아빠, 자전거 타는 법을 끝까지 가르쳐 주셔서 고맙습니다. 이제 혼자서도 탈 수 있어요. — 시우 올림","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#1','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C1',1,'mc','auto','고운 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01','K2-1-u7-X03']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"고운 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"듣는 사람을 생각하며 하는 말이에요","correct":true},{"t":"크게 소리치는 말이에요","mis":"K2-1-u7-X01"},{"t":"선생님께만 쓰는 말이에요","mis":"K2-1-u7-X03"}],"explanation":["고운 말은 듣는 사람을 생각하는 말이에요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#2','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「괜찮아, 다시 하면 돼.」","correct":true},{"t":"「또 틀렸어?」","mis":"K2-1-u7-X03"},{"t":"「느림보야.」","mis":"K2-1-u7-X03"}],"explanation":["「괜찮아, 다시 하면 돼.」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#3','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 우산이 없어서 현관에 서 있던 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 우산이 없어서 현관에 서 있던 인물은 누구인가요?","options":[{"t":"서준","correct":true},{"t":"아린","mis":"K2-1-u7-X05"},{"t":"엄마","mis":"K2-1-u7-X04"}],"explanation":["서준이가 우산이 없어서 현관에 서 있었어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#4','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 수빈이가 감자를 캔 곳은 어디인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이가 감자를 캔 곳은 어디인가요?","options":[{"t":"할머니 댁 텃밭","correct":true},{"t":"동네 공원","mis":"K2-1-u7-X05"},{"t":"학교 화단","mis":"K2-1-u7-X04"}],"explanation":["「할머니 댁 텃밭에서」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#5','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C6',1,'mc','auto','친구의 발표를 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"발표하는 친구를 바라보며 끝까지 들어요","correct":true},{"t":"짝과 이야기하며 들어요","mis":"K2-1-u7-X11"},{"t":"중간에 끼어들어요","mis":"K2-1-u7-X11"}],"explanation":["끝까지 바라보며 들으면 친구가 힘이 나요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#6','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C8',1,'mc','auto','친구에게 기쁜 일이 생겼을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"친구에게 기쁜 일이 생겼을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「축하해.」","correct":true},{"t":"「미안해.」","mis":"K2-1-u7-X02"},{"t":"「괜찮아?」","mis":"K2-1-u7-X02"}],"explanation":["기쁜 일에는 「축하해.」라고 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#7','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「내 짝 필통은 파란색인 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「내 짝 필통은 파란색인 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"내 짝 필통은 파란색이에요.","correct":true},{"t":"내 짝 필통은 파란색이었던 것 같아요.","mis":"K2-1-u7-X17"},{"t":"내 짝 필통은 파란색일 것 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「내 짝 필통은 파란색이에요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#8','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C10',1,'ox','auto','마음 쪽지에는 무엇이 고마운지 까닭을 함께 쓰면 좋아요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"마음 쪽지에는 무엇이 고마운지 까닭을 함께 쓰면 좋아요.","answer":"O","reason_options":[{"t":"까닭을 쓰면 마음이 더 잘 전해지니까","correct":true},{"t":"까닭을 쓰면 쪽지가 길어져서 안 되니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["무엇이 고마운지 알면 받는 사람이 더 기뻐요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#9','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"빨리 해!","r":"조금만 서둘러 줄 수 있니?"},{"l":"저리 가!","r":"지금은 혼자 있고 싶어."},{"l":"또 틀렸어?","r":"다음엔 더 잘할 거야."}],"mis":"K2-1-u7-X02","explanation":["「빨리 해!」 → 「조금만 서둘러 줄 수 있니?」","「저리 가!」 → 「지금은 혼자 있고 싶어.」","「또 틀렸어?」 → 「다음엔 더 잘할 거야.」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#10','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 아린이와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 아린이와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"태민 — 「짐이 많은 할머니를 도와드리고 뿌듯했어.」","correct":true},{"t":"소율 — 「나는 우산이 세 개 있어.」","mis":"K2-1-u7-X07"},{"t":"현우 — 「비가 오면 길이 미끄러워.」","mis":"K2-1-u7-X07"}],"explanation":["남을 도와 뿌듯했던 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#11','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 수빈이의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"다음에도 할머니와 함께 감자를 캐고 싶어요.","correct":true},{"t":"저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","mis":"K2-1-u7-X06"},{"t":"호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","mis":"K2-1-u7-X06"}],"explanation":["「캐고 싶어요」에 수빈이의 생각이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 지난 토요일에 할머니 댁 텃밭에서 감자를 캤어요.","호미로 흙을 살살 파니 동글동글한 감자가 줄줄이 나왔어요.","생각보다 감자가 많이 나와서 깜짝 놀랐어요.","다음에도 할머니와 함께 감자를 캐고 싶어요."],"title":"수빈이의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#12','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 물뿌리개를 들 때 민지의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 물뿌리개를 들 때 민지의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"팔이 아프고 힘들었다","correct":true},{"t":"가볍고 신났다","mis":"K2-1-u7-X13"},{"t":"미안하고 부끄러웠다","mis":"K2-1-u7-X13"}],"explanation":["민지는 무거워서 팔이 아프다고 했어요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#13','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"엉엉","r":"크게 소리 내어 우는 소리"},{"l":"방긋","r":"소리 없이 살짝 웃는 모양"},{"l":"데굴데굴","r":"큰 물건이 계속 구르는 모양"}],"mis":"K2-1-u7-X14","explanation":["「엉엉」 — 크게 소리 내어 우는 소리","「방긋」 — 소리 없이 살짝 웃는 모양","「데굴데굴」 — 큰 물건이 계속 구르는 모양"],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#14','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"본 것 같아요","r":"봤어요"},{"l":"기뻤던 것 같아요","r":"기뻤어요"},{"l":"좋은 것 같아요","r":"좋아요"}],"mis":"K2-1-u7-X17","explanation":["「본 것 같아요」 → 「봤어요」","「기뻤던 것 같아요」 → 「기뻤어요」","「좋은 것 같아요」 → 「좋아요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#15','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 로아의 판 첫째 줄 맨 끝 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 로아의 판 첫째 줄 맨 끝 칸에 있는 말은 어느 것인가요?","options":[{"t":"같이 하자","correct":true},{"t":"고마워","mis":"K2-1-u7-X04"},{"t":"잘했어","mis":"K2-1-u7-X04"}],"explanation":["첫째 줄은 고마워 · 괜찮아 · 같이 하자예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 고마워 · 괜찮아 · 같이 하자","둘째 줄: 힘내 · 미안해 · 잘했어","셋째 줄: 도와줄게 · 넌 소중해 · 걱정하지 마"],"title":"로아의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#16','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C6',2,'error','auto','발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X11','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"건우 — 발표 중간에 「그거 아니야!」 하고 끼어들었어요.","correct":true,"mis_target":"K2-1-u7-X11"},{"t":"예린 — 발표하는 친구를 바라보며 끝까지 들었어요.","mis":"K2-1-u7-X18"},{"t":"도담 — 발표가 끝난 뒤 손을 들고 물어봤어요.","mis":"K2-1-u7-X18"}],"explanation":["중간에 끼어들면 발표가 끊겨요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#17','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 실수로 내 색종이를 찢었어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X02']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 실수로 내 색종이를 찢었어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「괜찮아, 새 색종이로 다시 하자.」","correct":true},{"t":"「너는 맨날 망쳐!」","mis":"K2-1-u7-X12"},{"t":"「찢어 줘서 고마워.」","mis":"K2-1-u7-X02"}],"explanation":["친구의 당황한 마음을 덜어 주었어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#18','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 토리가 엉엉 울게 된 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 토리가 엉엉 울게 된 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"겨울에 먹으려고 모은 도토리가 웅덩이에 빠져서","correct":true},{"t":"거북 할아버지가 도토리를 가져가서","mis":"K2-1-u7-X04"},{"t":"도토리 과자가 맛이 없어서","mis":"K2-1-u7-X05"}],"explanation":["모아 둔 도토리가 빠져서 울었어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["꼬마 다람쥐 토리는 도토리를 데굴데굴 굴리며 집으로 갔어요.","그런데 도토리가 그만 웅덩이에 퐁당 빠지고 말았어요.","토리는 엉엉 울었어요. 「겨울에 먹으려고 모은 건데…….」","거북 할아버지가 엉금엉금 다가와 도토리를 건져 주었어요.","토리는 방긋 웃으며 말했어요. 「할아버지, 정말 고맙습니다!」","다음 날 토리는 도토리 과자를 만들어 할아버지께 드렸어요."],"title":"토리의 도토리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#19','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 쪽지를 받는 사람과 쓴 사람을 바르게 말한 것은 어느 것인가요?","options":[{"t":"받는 사람: 지호 · 쓴 사람: 서아","correct":true},{"t":"받는 사람: 서아 · 쓴 사람: 지호","mis":"K2-1-u7-X15"},{"t":"받는 사람: 선생님 · 쓴 사람: 서아","mis":"K2-1-u7-X15"}],"explanation":["첫 줄에 받는 사람, 끝 줄에 쓴 사람이 있어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["지호에게","지호야, 어제 내가 필통을 놓고 왔을 때 연필을 빌려줘서 고마워.","덕분에 받아쓰기를 끝까지 할 수 있었어.","다음에는 내가 너를 도와줄게.","— 서아가"],"title":"서아의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#20','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"현우 — 「아린이처럼 나도 우산이 없어 곤란했어.」","correct":true,"mis_target":"K2-1-u7-X05"},{"t":"다은 — 「서준이처럼 나도 비 오는 날 우산을 빌려 써서 고마웠어.」","mis":"K2-1-u7-X18"},{"t":"지안 — 「아린이처럼 나도 동생 숙제를 도와주고 뿌듯했어.」","mis":"K2-1-u7-X18"}],"explanation":["우산이 없어 곤란했던 인물은 서준이에요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["수업이 끝나자 갑자기 비가 쏟아졌어요.","서준이는 우산이 없어서 현관에 우두커니 서 있었어요.","그때 아린이가 다가와 말했어요. 「내 우산 같이 쓰자. 우리 집도 같은 쪽이야.」","둘은 우산 하나를 나란히 쓰고 집까지 걸어갔어요.","서준이가 말했어요. 「고마워, 아린아. 덕분에 비를 안 맞았어.」","아린이는 친구를 도울 수 있어서 마음이 뿌듯했어요."],"title":"같이 쓴 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#21','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C12',3,'ox','auto','「친구가 웃는 걸 보니 기분이 좋은 것 같아요.」는 알맞은 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「친구가 웃는 걸 보니 기분이 좋은 것 같아요.」는 알맞은 말이에요.","answer":"O","reason_options":[{"t":"친구의 마음은 짐작하는 것이니까","correct":true},{"t":"남의 마음도 언제나 확실히 알 수 있으니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["다른 사람의 마음을 짐작할 때는 「것 같아요」를 써요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#22','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C1',3,'mc','auto','「조용히 해!」와 「조금만 작게 말해 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「조용히 해!」와 「조금만 작게 말해 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「조금만 작게 말해 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「조용히 해!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#23','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C5',4,'essay','teacher','친구와 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"친구와 함께한 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 어제 쉬는 시간에 운동장에서 친구들과 술래잡기를 했어요. 숨이 찰 만큼 뛰었지만 너무 즐거웠어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#24','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 하람이가 처음 한 말을 지호의 마음을 생각한 고운 말로 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 하람이가 처음 한 말을 지호의 마음을 생각한 고운 말로 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.","answer_guide":{"answer":"예: 「여기부터 줄이야. 뒤에 서 줄래?」 왜냐하면 지호는 줄이 어디까지인지 몰라서 그런 것이니 탓하지 않고 알려 주는 것이 좋기 때문이에요.","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"하람","text":"왜 내 앞에 끼어드는 거야?"},{"who":"지호","text":"아, 줄이 여기까지인 줄 몰랐어. 미안해, 뒤로 갈게."},{"who":"하람","text":"나도 큰 소리 내서 미안해. 줄이 길어서 헷갈렸겠다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_c#25','kor',2,1,'u7','','g2_1_kor_u7_review_c','unit_review','K2-1-u7-C10',4,'essay','teacher','내가 속상하게 한 친구에게 미안한 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"내가 속상하게 한 친구에게 미안한 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 다은이에게 — 다은아, 어제 네 그림을 보고 이상하다고 해서 미안해. 사실은 색깔이 참 예뻤어. — 지후가","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#1','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C1',1,'mc','auto','「힘내, 할 수 있어!」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":1,"concept":"K2-1-u7-C1","difficulty":1,"kind":"mc","stem":"「힘내, 할 수 있어!」라는 말을 들은 친구의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"든든하고 힘이 난다","correct":true},{"t":"창피하고 화가 난다","mis":"K2-1-u7-X01"},{"t":"슬프고 외롭다","mis":"K2-1-u7-X01"}],"explanation":["응원하는 고운 말은 친구에게 힘을 줘요.","다른 보기는 말이 마음에 주는 힘을 생각하지 않았어요.","내가 들었다면 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#2','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C2',1,'mc','auto','들으면 기분이 좋아지는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X03']::text[],false,'{"seq":2,"concept":"K2-1-u7-C2","difficulty":1,"kind":"mc","stem":"들으면 기분이 좋아지는 고운 말은 어느 것인가요?","options":[{"t":"「잘했어!」","correct":true},{"t":"「메롱.」","mis":"K2-1-u7-X03"},{"t":"「넌 원래 그래.」","mis":"K2-1-u7-X03"}],"explanation":["「잘했어!」는 듣는 사람을 생각하는 고운 말이에요.","다른 두 말은 마음을 아프게 하는 거친 말이에요.","내가 들었다면 기분이 어땠을지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#3','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C3',1,'mc','auto','이야기를 읽고 답해 보세요. 「나는 못 하겠어.」라고 말한 인물은 누구인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":3,"concept":"K2-1-u7-C3","difficulty":1,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 「나는 못 하겠어.」라고 말한 인물은 누구인가요?","options":[{"t":"시우","correct":true},{"t":"아빠","mis":"K2-1-u7-X05"},{"t":"동생","mis":"K2-1-u7-X04"}],"explanation":["시우가 넘어진 뒤 그렇게 말했어요.","다른 보기는 다른 인물이거나 이야기에 없어요.","이야기에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#4','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C5',1,'mc','auto','발표를 읽고 답해 보세요. 준우가 연을 날린 때는 언제인가요?',ARRAY['K2-1-u7-X05','K2-1-u7-X04']::text[],false,'{"seq":4,"concept":"K2-1-u7-C5","difficulty":1,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우가 연을 날린 때는 언제인가요?","options":[{"t":"어제 저녁","correct":true},{"t":"지난 토요일","mis":"K2-1-u7-X05"},{"t":"오늘 아침","mis":"K2-1-u7-X04"}],"explanation":["「어제 저녁에」라고 했어요.","다른 보기는 다른 친구의 발표에 나오거나 발표에 없어요.","발표에서 그 문장을 찾아 짚어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#5','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C6',1,'mc','auto','친구의 발표를 들을 때 바른 자세는 어느 것인가요?',ARRAY['K2-1-u7-X11']::text[],false,'{"seq":5,"concept":"K2-1-u7-C6","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 바른 자세는 어느 것인가요?","options":[{"t":"궁금한 것은 발표가 끝난 뒤 손을 들고 물어봐요","correct":true},{"t":"궁금하면 바로 소리쳐 물어봐요","mis":"K2-1-u7-X11"},{"t":"책상에 엎드려 들어요","mis":"K2-1-u7-X11"}],"explanation":["발표가 끝난 뒤 손을 들고 물어봐요.","다른 보기는 바르지 않은 자세예요.","맨 뒤 친구가 잘 듣고 볼 수 있는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#6','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C8',1,'mc','auto','친구가 넘어져 다쳤을 때 하는 고운 말은 어느 것인가요?',ARRAY['K2-1-u7-X02']::text[],false,'{"seq":6,"concept":"K2-1-u7-C8","difficulty":1,"kind":"mc","stem":"친구가 넘어져 다쳤을 때 하는 고운 말은 어느 것인가요?","options":[{"t":"「괜찮아? 많이 아프지?」","correct":true},{"t":"「축하해.」","mis":"K2-1-u7-X02"},{"t":"「고마워.」","mis":"K2-1-u7-X02"}],"explanation":["다친 친구에게는 마음을 살피는 말을 해요.","다른 보기는 상황과 맞지 않는 말이에요.","고마운 일·미안한 일·기쁜 일을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#7','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C12',1,'mc','auto','내가 직접 겪은 일을 말할 때 「숙제를 다 한 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":7,"concept":"K2-1-u7-C12","difficulty":1,"kind":"mc","stem":"내가 직접 겪은 일을 말할 때 「숙제를 다 한 것 같아요.」를 또렷하게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"숙제를 다 했어요.","correct":true},{"t":"숙제를 다 했던 것 같아요.","mis":"K2-1-u7-X17"},{"t":"숙제를 다 한 것도 같아요.","mis":"K2-1-u7-X17"}],"explanation":["직접 겪은 확실한 일은 「숙제를 다 했어요.」처럼 또렷하게 말해요.","「것 같아요」를 그대로 두거나 더 붙이면 또렷하지 않아요.","「내가 직접 겪었나?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#8','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C10',1,'ox','auto','미안한 마음은 쪽지에 「미안해.」 한 마디만 쓰면 충분해요.',ARRAY['K2-1-u7-X15']::text[],false,'{"seq":8,"concept":"K2-1-u7-C10","difficulty":1,"kind":"ox","stem":"미안한 마음은 쪽지에 「미안해.」 한 마디만 쓰면 충분해요.","answer":"X","reason_options":[{"t":"무엇이 미안한지 함께 써야 마음이 잘 전해지니까","correct":true},{"t":"미안한 까닭은 숨겨야 하니까","mis":"K2-1-u7-X15"}],"mis":"K2-1-u7-X15","explanation":["무엇이 미안한지 쓰면 사과가 진심으로 전해져요.","마음은 고운 말로 표현해야 전해져요.","누구에게 · 어떤 마음 · 왜를 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#9','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C2',2,'match','auto','거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u7-C2","difficulty":2,"kind":"match","stem":"거친 말을 같은 뜻의 고운 말로 알맞게 바꾸어 이어 보세요.","pairs":[{"l":"문 닫아!","r":"문 좀 닫아 줄래?"},{"l":"그만해!","r":"조금만 조용히 해 줄래?"},{"l":"줘!","r":"나도 써 봐도 될까?"}],"mis":"K2-1-u7-X02","explanation":["「문 닫아!」 → 「문 좀 닫아 줄래?」","「그만해!」 → 「조금만 조용히 해 줄래?」","「줘!」 → 「나도 써 봐도 될까?」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#10','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C4',2,'mc','auto','이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?',ARRAY['K2-1-u7-X07']::text[],false,'{"seq":10,"concept":"K2-1-u7-C4","difficulty":2,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 시우와 비슷한 경험을 떠올린 친구는 누구인가요?","options":[{"t":"민준 — 「줄넘기에 자꾸 걸렸지만 계속 연습해서 성공했어.」","correct":true},{"t":"서아 — 「우리 아빠는 키가 커.」","mis":"K2-1-u7-X07"},{"t":"지호 — 「자전거 바퀴는 둥글어.」","mis":"K2-1-u7-X07"}],"explanation":["처음엔 실패했지만 끝내 해낸 경험이에요.","다른 보기는 겪은 일이 아니거나 이야기와 상관없어요.","「그때 인물과 비슷한 마음이었나?」 물어봐요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#11','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C5',2,'mc','auto','발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?',ARRAY['K2-1-u7-X06']::text[],false,'{"seq":11,"concept":"K2-1-u7-C5","difficulty":2,"kind":"mc","stem":"발표를 읽고 답해 보세요. 준우의 생각이나 느낌이 드러난 문장은 어느 것인가요?","options":[{"t":"다음에는 더 큰 연을 만들어 날리고 싶어요.","correct":true},{"t":"저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","mis":"K2-1-u7-X06"},{"t":"바람이 세게 불자 연이 하늘 높이 올라갔어요.","mis":"K2-1-u7-X06"}],"explanation":["「날리고 싶어요」에 준우의 생각이 드러나요.","다른 두 문장은 있었던 일을 말한 문장이에요.","「무엇을 했지?」와 「어떤 마음이었지?」를 나눠 물어요."],"asset":{"type":"passage","lines":["저는 어제 저녁에 동네 공원에서 동생과 연을 날렸어요.","바람이 세게 불자 연이 하늘 높이 올라갔어요.","연줄을 꼭 잡느라 손이 얼얼했지만 정말 신났어요.","다음에는 더 큰 연을 만들어 날리고 싶어요."],"title":"준우의 경험 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#12','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C7',2,'mc','auto','대화를 읽고 답해 보세요. 「일부러 그런 거 아닌데…….」라고 말할 때 예린이의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X13']::text[],false,'{"seq":12,"concept":"K2-1-u7-C7","difficulty":2,"kind":"mc","stem":"대화를 읽고 답해 보세요. 「일부러 그런 거 아닌데…….」라고 말할 때 예린이의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"미안하면서도 억울하다","correct":true},{"t":"신나고 자랑스럽다","mis":"K2-1-u7-X13"},{"t":"블록 탑이 무너져 기쁘다","mis":"K2-1-u7-X13"}],"explanation":["일부러가 아니어서 억울하고, 탑이 무너져 미안했을 거예요.","다른 보기는 상황에 맞지 않는 마음이에요.","내가 그 사람이라면 어떤 마음일지 생각해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"야! 너 때문에 내 블록 탑이 다 무너졌잖아!"},{"who":"예린","text":"일부러 그런 거 아닌데……."},{"who":"도윤","text":"몰라, 저리 가!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#13','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C9',2,'match','auto','이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":13,"concept":"K2-1-u7-C9","difficulty":2,"kind":"match","stem":"이야기를 읽고 흉내 내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"쏙","r":"좁은 데서 쉽게 빠져나오는 모양"},{"l":"생글생글","r":"눈과 입으로 귀엽게 웃는 모양"},{"l":"둥실둥실","r":"가볍게 떠오르는 모양"}],"mis":"K2-1-u7-X14","explanation":["「쏙」 — 좁은 데서 쉽게 빠져나오는 모양","「생글생글」 — 눈과 입으로 귀엽게 웃는 모양","「둥실둥실」 — 가볍게 떠오르는 모양"],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#14','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C12',2,'match','auto','직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.','{}'::text[],false,'{"seq":14,"concept":"K2-1-u7-C12","difficulty":2,"kind":"match","stem":"직접 겪은 일을 「것 같아요」 없이 또렷한 말로 알맞게 이어 보세요.","pairs":[{"l":"읽은 것 같아요","r":"읽었어요"},{"l":"무서웠던 것 같아요","r":"무서웠어요"},{"l":"시원한 것 같아요","r":"시원해요"}],"mis":"K2-1-u7-X17","explanation":["「읽은 것 같아요」 → 「읽었어요」","「무서웠던 것 같아요」 → 「무서웠어요」","「시원한 것 같아요」 → 「시원해요」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#15','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C11',2,'mc','auto','맞추기판을 읽고 답해 보세요. 지안이의 판 셋째 줄 맨 끝 칸에 있는 말은 어느 것인가요?',ARRAY['K2-1-u7-X04']::text[],false,'{"seq":15,"concept":"K2-1-u7-C11","difficulty":2,"kind":"mc","stem":"맞추기판을 읽고 답해 보세요. 지안이의 판 셋째 줄 맨 끝 칸에 있는 말은 어느 것인가요?","options":[{"t":"최고야","correct":true},{"t":"미안해","mis":"K2-1-u7-X04"},{"t":"사랑해","mis":"K2-1-u7-X04"}],"explanation":["셋째 줄은 미안해 · 힘내 · 최고야예요.","다른 보기는 판의 그 자리에 없어요.","판에서 말을 하나씩 짚어 봐요."],"asset":{"type":"passage","lines":["첫째 줄: 축하해 · 멋지다 · 고마워","둘째 줄: 괜찮아? · 같이 놀자 · 사랑해","셋째 줄: 미안해 · 힘내 · 최고야"],"title":"지안이의 고운 말 맞추기판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#16','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C6',2,'error','auto','발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?',ARRAY['K2-1-u7-X11','K2-1-u7-X18']::text[],false,'{"seq":16,"concept":"K2-1-u7-C6","difficulty":2,"kind":"error","stem":"발표를 듣는 모습이에요. 바르지 않은 친구는 누구인가요?","options":[{"t":"은솔 — 발표하는 동안 짝과 귓속말을 했어요.","correct":true,"mis_target":"K2-1-u7-X11"},{"t":"하늘 — 고개를 끄덕이며 끝까지 들었어요.","mis":"K2-1-u7-X18"},{"t":"민지 — 발표가 끝나자 박수를 쳤어요.","mis":"K2-1-u7-X18"}],"explanation":["귓속말을 하면 발표를 놓쳐요.","다른 두 친구는 바른 자세였어요.","맨 뒤 친구까지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#17','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C8',3,'mc','auto','친구가 줄을 잘못 알고 내 앞에 섰어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X12','K2-1-u7-X03']::text[],false,'{"seq":17,"concept":"K2-1-u7-C8","difficulty":3,"kind":"mc","stem":"친구가 줄을 잘못 알고 내 앞에 섰어요. 마음을 생각하며 고운 말로 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여기부터 줄이야. 헷갈렸지? 뒤에 서 줄래?」","correct":true},{"t":"「왜 새치기해? 나쁜 애야!」","mis":"K2-1-u7-X12"},{"t":"「하하, 줄도 몰라?」","mis":"K2-1-u7-X03"}],"explanation":["헷갈린 친구의 마음을 헤아리며 부탁했어요.","화난 기분만 쏟아 내면 다툼이 커져요.","「일부러 그랬을까?」 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#18','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C9',3,'mc','auto','이야기를 읽고 답해 보세요. 하윤이가 시무룩해진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u7-X04','K2-1-u7-X05']::text[],false,'{"seq":18,"concept":"K2-1-u7-C9","difficulty":3,"kind":"mc","stem":"이야기를 읽고 답해 보세요. 하윤이가 시무룩해진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"풍선이 날아가 나뭇가지에 걸려서","correct":true},{"t":"건우 형이 풍선을 터뜨려서","mis":"K2-1-u7-X04"},{"t":"풍선을 하나 더 받아서","mis":"K2-1-u7-X05"}],"explanation":["풍선을 놓쳐 나뭇가지에 걸려서 시무룩했어요.","다른 보기는 이야기의 차례나 인물과 맞지 않아요.","일이 일어난 차례에 따라 마음을 짚어요."],"asset":{"type":"passage","lines":["하윤이는 놀이공원에서 받은 빨간 풍선을 들고 있었어요.","바람이 휙 불자 풍선 줄이 손에서 쏙 빠져나갔어요.","풍선은 둥실둥실 떠올라 나뭇가지에 걸렸어요.","하윤이는 시무룩해졌어요.","지나가던 건우 형이 깡충 뛰어올라 풍선 줄을 잡아 주었어요.","하윤이는 생글생글 웃으며 말했어요. 「형, 고마워요! 이제 꼭 잡을게요.」"],"title":"하윤이의 빨간 풍선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#19','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C10',3,'mc','auto','쪽지를 읽고 답해 보세요. 민호가 앞으로 하겠다고 다짐한 일은 어느 것인가요?',ARRAY['K2-1-u7-X15','K2-1-u7-X04']::text[],false,'{"seq":19,"concept":"K2-1-u7-C10","difficulty":3,"kind":"mc","stem":"쪽지를 읽고 답해 보세요. 민호가 앞으로 하겠다고 다짐한 일은 어느 것인가요?","options":[{"t":"내일부터 일찍 일어나기","correct":true},{"t":"엄마께 선물 사 드리기","mis":"K2-1-u7-X15"},{"t":"숙제 먼저 하기","mis":"K2-1-u7-X04"}],"explanation":["쪽지에 일찍 일어나겠다고 썼어요.","다른 보기는 쪽지 내용과 맞지 않아요.","누구에게 · 어떤 마음 · 왜를 찾아요."],"asset":{"type":"passage","lines":["엄마께","엄마, 오늘 아침에 짜증 내서 죄송해요.","늦잠을 자서 마음이 급했어요.","내일부터는 일찍 일어날게요. 사랑해요.","— 민호 올림"],"title":"민호의 마음 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#20','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C4',3,'error','auto','이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['K2-1-u7-X07','K2-1-u7-X18']::text[],false,'{"seq":20,"concept":"K2-1-u7-C4","difficulty":3,"kind":"error","stem":"이야기를 읽고 인물의 경험과 내 경험을 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"하준 — 「시우처럼 나도 아빠를 도와드리고 칭찬받았어.」","correct":true,"mis_target":"K2-1-u7-X07"},{"t":"채원 — 「시우처럼 나도 처음엔 무서웠지만 끝까지 해냈어.」","mis":"K2-1-u7-X18"},{"t":"지우 — 「시우처럼 나도 넘어져서 무릎이 까진 적이 있어.」","mis":"K2-1-u7-X18"}],"explanation":["시우는 도와드린 것이 아니라 어려운 일을 연습해서 해냈어요.","다른 두 친구는 바르게 비교했어요.","누구의 일인지, 비슷한 마음인지 살펴요."],"asset":{"type":"passage","lines":["시우는 아빠와 공원에서 두발자전거 타기를 연습했어요.","처음에는 자꾸 기우뚱거리다가 꽈당 넘어져 무릎이 까졌어요.","「나는 못 하겠어.」 시우는 울상이 되었어요.","아빠가 말했어요. 「괜찮아. 아빠가 뒤에서 잡아 줄게.」","몇 번을 더 연습하자 어느새 시우 혼자 자전거를 타고 있었어요.","시우는 하늘을 날 것처럼 기뻤어요."],"title":"처음 혼자 탄 자전거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#21','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C12',3,'ox','auto','「내 생일은 오월인 것 같아요.」는 또렷한 말이에요.',ARRAY['K2-1-u7-X17']::text[],false,'{"seq":21,"concept":"K2-1-u7-C12","difficulty":3,"kind":"ox","stem":"「내 생일은 오월인 것 같아요.」는 또렷한 말이에요.","answer":"X","reason_options":[{"t":"내 생일은 확실히 아는 일이니 「오월이에요.」라고 해야 하니까","correct":true},{"t":"「것 같아요」를 붙여야 겸손한 말이니까","mis":"K2-1-u7-X17"}],"mis":"K2-1-u7-X17","explanation":["확실히 아는 일은 「오월이에요.」처럼 또렷하게 말해요.","직접 겪은 확실한 일은 또렷하게 말해요.","짐작하는 일에는 「것 같아요」를 써도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#22','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C1',3,'mc','auto','「빨리 와!」와 「조금만 서둘러 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u7-X01']::text[],false,'{"seq":22,"concept":"K2-1-u7-C1","difficulty":3,"kind":"mc","stem":"「빨리 와!」와 「조금만 서둘러 줄래?」 두 말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 「조금만 서둘러 줄래?」가 듣는 사람의 기분을 더 좋게 해요","correct":true},{"t":"뜻이 같으니 듣는 사람의 기분도 똑같아요","mis":"K2-1-u7-X01"},{"t":"「빨리 와!」가 짧으니 더 고운 말이에요","mis":"K2-1-u7-X01"}],"explanation":["같은 부탁이라도 고운 말이 듣는 사람의 기분을 좋게 해요.","뜻이 같아도 말투에 따라 기분이 달라져요.","짧다고 고운 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#23','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C5',4,'essay','teacher','밖에 나가서 본 것이 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u7-C5","difficulty":4,"kind":"essay","stem":"밖에 나가서 본 것이 기억에 남는 경험을 하나 떠올려, 언제·어디에서·무슨 일이 있었는지와 그때의 생각이나 느낌이 모두 들어가게 발표할 내용을 써 보세요.","answer_guide":{"answer":"예: 지난 방학에 수목원에서 커다란 연꽃을 보았어요. 접시보다 큰 꽃잎을 보고 깜짝 놀랐어요.","scoring_points":["언제와 어디에서를 썼는가","무슨 일이 있었는지 자세히 썼는가","그때의 생각이나 느낌을 썼는가"]},"explanation":["언제·어디에서.","무슨 일.","생각이나 느낌."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#24','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C8',4,'essay','teacher','대화를 읽고 답해 보세요. 내가 현우라면 민지에게 어떤 고운 말을 하며 도와줄지 쓰고, 민지가 고맙다고 할 때 대답할 고운 말도 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u7-C8","difficulty":4,"kind":"essay","stem":"대화를 읽고 답해 보세요. 내가 현우라면 민지에게 어떤 고운 말을 하며 도와줄지 쓰고, 민지가 고맙다고 할 때 대답할 고운 말도 써 보세요.","answer_guide":{"answer":"예: 「무겁지? 내가 같이 들어 줄게.」 민지가 고맙다고 하면 「도움이 되어서 나도 기뻐.」라고 대답하겠어요.","scoring_points":["인물의 마음을 짐작해 썼는가","상황에 맞는 고운 말을 썼는가","대화의 흐름에 맞게 썼는가"]},"explanation":["인물의 마음.","고운 말.","대화 흐름."],"asset":{"type":"speech","turns":[{"who":"민지","text":"물뿌리개가 너무 무거워서 팔이 아파."},{"who":"현우","text":"내가 같이 들어 줄게. 한쪽을 잡을게."},{"who":"민지","text":"고마워, 현우야. 한결 가벼워졌어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u7_review_d#25','kor',2,1,'u7','','g2_1_kor_u7_review_d','unit_review','K2-1-u7-C10',4,'essay','teacher','기쁜 일이 생긴 친구에게 축하하는 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u7-C10","difficulty":4,"kind":"essay","stem":"기쁜 일이 생긴 친구에게 축하하는 마음을 전하는 마음 쪽지를 써 보세요. 받는 사람·전하고 싶은 마음·그 까닭이 모두 드러나게 고운 말로 써 보세요.","answer_guide":{"answer":"예: 로아에게 — 로아야, 받아쓰기에서 백 점 받은 거 축하해. 날마다 연습하더니 정말 멋지다. — 은솔이가","scoring_points":["받는 사람과 쓴 사람을 밝혔는가","전하고 싶은 마음과 그 까닭을 썼는가","고운 말로 썼는가"]},"explanation":["받는 사람·쓴 사람.","마음과 까닭.","고운 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
